NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'Judges'

CHAPTERS = {
    1: {
        1: 'Und nach Josues Tode fragten die Söhne Israels den Herrn: "Wer von uns soll zuerst in den Kampf wider die Kanaaniter ziehen?"',
        2: 'Da sprach der Herr: "Juda soll hinziehen! Ich gebe das Land in seine Hand."',
        3: 'Da sprach Juda zu seinem Bruder Simeon: "Zieh mit mir in mein Losteil! Wir wollen wider die Kanaaniter streiten. Dann ziehe auch ich mit dir in dein Losteil." Und Simeon zog mit ihm.',
        4: 'Juda zog nun hin, und der Herr gab die Kanaaniter und die Periziter in seine Hand. Sie schlugen diese bei Bezek, 10.000 Mann.',
        5: 'In Bezek stießen sie auf den Zepterträger, kämpften mit ihm und schlugen die Kanaaniter und Periziter.',
        6: 'Der Zepterträger jedoch floh. Sie aber jagten ihm nach, griffen ihn und hieben ihm die Daumen und die großen Zehen ab.',
        7: 'Da sprach der Zepterträger: "Siebzig Könige mit abgehauenen Daumen und Zehen haben unter meinem Tische aufgelesen. Wie ich getan, so hat mir Gott vergolten." Dann brachten sie ihn nach Jerusalem, und er erlitt dort den Tod.',
        8: 'Judas Söhne kämpften nämlich gegen Jerusalem, eroberten es und schlugen es mit des Schwertes Schärfe und steckten die Stadt in Brand.',
        9: 'Danach zogen Judas Söhne zum Kampfe gegen die Kanaaniter hinab, die das Gebirge, das Südland und die Niederung bewohnten.',
        10: 'Und Juda zog gegen die Kanaaniter in Hebron. Hebron aber hieß vormals Kirjat Arba. Sie schlugen Sesai, Achiman und Talmai.',
        11: 'Von dort zogen sie gegen Debirs Einwohner. Debir hieß vormals Kirjat Sepher.',
        12: 'Und Kaleb sprach: "Wer Kirjat Sepher bezwingt und einnimmt, dem gebe ich meine Tochter Aksa zum Weibe."',
        13: 'Da nahm es des Kenaz Sohn Otniel, Kalebs jüngerer Bruder. Da gab er ihm seine Tochter Aksa zum Weibe.',
        14: 'Als sie hinzog, überlistete sie ihren Vater, da sie von ihm ein Feld wollte. Sie neigte sich nämlich vom Esel, so daß Kaleb sie fragte: "Was ist dir?"',
        15: 'Sie aber sprach zu ihm: "Gib mir doch eine Abschiedsgabe! Du vergibst mich ja nach dem Südland. So gib mir Wasser!" Da gab ihr Kaleb oberirdische und unterirdische Wasserstellen.',
        16: 'Die Söhne des Keniters, des Schwiegervaters Mosis, waren aus der Palmenstadt zu den Söhnen Judas nach der Wüste Juda im Rücken Arads hinauf gezogen. Diese aber zogen ab und verpflanzten das Volk.',
        17: 'Auch Juda zog mit seinem Bruder Simeon weiter. Sie schlugen die Kanaaniter zu Sephat und bannten es. Daher nannte man die Stadt Chorma.',
        18: 'Dann eroberte Juda Gaza, Askalon und Ekron je mit ihrem Gebiet.',
        19: 'Und der Herr war mit Juda, und es besetzte das Gebirge; die Talbewohner nämlich konnte es nicht vertreiben, weil sie eiserne Wagen hatten.',
        20: 'Sie gaben nun Hebron dem Kaleb, wie es Moses befohlen. Und er vertrieb daraus die Enaksöhne.',
        21: 'Auch die Benjaminiten konnten die Jebusiter, Jerusalems Insassen, nicht vertreiben. So blieben die Jebusiter bei den Söhnen Benjamins bis auf diesen Tag.',
        22: 'Auch die vom Hause Josephs zogen gegen Betel, und der Herr war mit ihnen.',
        23: 'Die vom Hause Josephs ließen nun Betel ausspähen. Die Stadt aber hieß vordem Luz.',
        24: 'Die Kundschafter sahen nun einen Mann aus der Stadt kommen und sagten zu ihm: "Zeig uns den Zugang zur Stadt! Wir erweisen dir dafür Gutes."',
        25: 'Da zeigte er ihnen den Zugang zur Stadt. Und sie schlugen die Stadt mit des Schwertes Schärfe. Den Mann aber ließen sie mit seiner ganzen Familie ziehen.',
        26: 'Da ging der Mann in das Chittiterland, baute eine Stadt und nannte sie Luz. So heißt sie bis auf diesen Tag.',
        27: 'Auch Manasse vertrieb nicht die Bewohner von Bet Sean, Taanak, Ibleam, Megiddo und ihren Dörfern. Den Kanaanitern nämlich gelang es, in diesem Lande zu bleiben.',
        28: 'Als aber Israel erstarkte, machte es die Kanaaniter zinsbar, vertrieb sie aber nicht ganz.',
        29: 'Auch Ephraim vertrieb nicht die kanaanitischen Insassen von Gezer. So blieben die Kanaaniter mitten unter ihm zu Gezer.',
        30: 'Auch Zabulon vertrieb nicht die Insassen von Kitron noch die von Nahalol. So blieben die Kanaaniter mitten unter ihm, wurden aber zinsbar.',
        31: 'Asser vertrieb nicht die Insassen von Akko und die von Sidon, Achlab, Akzib, Helba, Aphik und Rechob.',
        32: 'So wohnten Assers Söhne mitten unter Kanaanitern, die im Lande blieben, weil man sie nicht vertrieb.',
        33: 'Naphtali vertrieb nicht die Insassen von Bet Semes noch die von Bet Anat. So wohnte es mitten unter den Kanaanitern, die im Lande blieben. Doch wurden die Einwohner von Bet Semes und Bet Anat ihnen zinsbar.',
        34: 'Die Amoriter aber drängten Dans Söhne auf das Gebirge; denn sie ließen sie nicht in die Ebene ziehen.',
        35: 'So gelang es den Amoritern, in Har Cheres, Ajjalon und Saalbin zu bleiben. Als aber die Macht des Josephhauses erstarkte, wurden sie zinsbar.',
        36: 'Das Amoritergebiet aber erstreckte sich von der Skorpionensteige, von dem Felsengebirge, weiter hinauf.',
    },
    2: {
        1: 'Des Herrn Bote aber zog von Gilgal nach Bokim und sprach: "Ich führte euch aus Ägypten und brachte euch in dies Land, das ich euren Vätern zugeschworen. Ich sprach: \'Ich breche nie mein Bündnis mit euch.',
        2: 'Aber auch ihr dürft mit den Bewohnern dieses Landes kein Bündnis schließen. Zerstören sollt ihr ihre Altäre!\' Ihr habt aber nicht auf meine Stimme gehört. Wie habt ihr solches tun können?"',
        3: 'So sage auch ich: "Ich will sie nicht vor euch vertreiben. Sie seien euch zur Schlinge, und ihre Götter seien euch zur Falle!"',
        4: 'Des Herrn Bote sprach nun diese Worte zu allen Söhnen Israels. Da erhob das Volk seine Stimme und weinte.',
        5: 'Und so nannte man einen Ort Bokim. Und sie opferten dort dem Herrn. -',
        6: 'Josue entließ nun das Volk. Da gingen die Israeliten, jeder nach seinem Erbbesitz, das Land zu besetzen.',
        7: 'Und das Volk diente dem Herrn alle Tage Josues und all der Ältesten, die Josue überlebt und die noch geschaut hatten jede Großtat des Herrn, die er für Israel getan.',
        8: 'Da starb Josue, Nuns Sohn, des Herrn Diener, hundertzehn Jahre alt.',
        9: 'Man begrub ihn im Bereiche seines Erbes zu Timnat Cheres auf dem Gebirge Ephraim, nördlich vom Berge Gaas.',
        10: 'Auch dies ganze Geschlecht ward zu seinen Vätern versammelt. Danach kam ein anderes Geschlecht, das den Herrn nicht kannte, noch das Werk, das er für Israel getan.',
        11: 'Und die Israeliten taten, was dem Herrn mißfiel, und dienten den Baalen.',
        12: 'Sie verließen den Herrn, ihrer Väter Gott, der sie aus Ägypten geführt, und liefen anderen Göttern nach, solchen aus den Göttern der Völker rings um sie. Sie beteten sie an und kränkten den Herrn.',
        13: 'Sie verließen also den Herrn und dienten den Baalen und den Astarten.',
        14: 'Da entbrannte des Herrn Zorn wider Israel. Er gab sie in die Hand der Plünderer, die sie ausraubten. So verkaufte er sie in die Hand ihrer Feinde ringsum, und sie konnten nicht ihren Feinden widerstehen.',
        15: 'Wohin sie zogen, war des Herrn Hand gegen sie zum Unheil, wie der Herr gesagt, und wie der Herr ihnen zugeschworen. Aber ihre Not ward zu groß.',
        16: 'So ließ der Herr Richter erstehen, und diese retteten sie aus ihrer Plünderer Hand.',
        17: 'Aber auch ihren Richtern gehorchten sie nicht, sondern buhlten hinter anderen Göttern her und beteten sie an. So wichen sie schnell von dem Wege ab, den ihre Väter gegangen, als sie des Herrn Geboten gehorchten. Sie aber taten nicht so.',
        18: 'Ließ ihnen der Herr Richter erstehen, so war der Herr mit dem Richter und bewahrte sie vor ihrer Feinde Hand alle Tage des Richters. Denn der Herr änderte seinen Sinn ob ihrer Klage über ihre Bedränger und Bedrücker.',
        19: 'Starb aber der Richter, so trieben sie es wieder schlimmer als ihre Väter. Sie liefen anderen Göttern nach, dienten ihnen und beteten sie an. Sie ließen nicht von ihren Missetaten und ihrem verkehrten Wandel.',
        20: 'Dann entbrannte des Herrn Zorn gegen Israel, und er sprach: "Weil dieses Volk mein Bündnis übertritt, das ich ihren Vätern befohlen, und nicht auf meine Stimme hört,',
        21: 'so vertreibe ich vor ihnen nicht einen Mann mehr aus jenen Heidenvölkern, die Josue bei seinem Tode hinterlassen hat,',
        22: 'um Israel durch sie zu prüfen, ob sie des Herrn Wandel achteten und danach wandelten, wie ihre Väter darauf geachtet, oder nicht."',
        23: 'So ließ der Herr jene Heidenvölker, ohne sie rasch zu vertilgen; er hatte sie nicht in Josues Hand gegeben.',
    },
    3: {
        1: 'Dies sind die Heidenvölker, die der Herr dagelassen hat, um durch sie Israel zu erproben in all dem, was sie noch nicht gekannt, in den Kämpfen mit Kanaan,',
        2: '- nur damit die Geschlechter der Israeliten das Kriegshandwerk zu erlernen verstünden, einzig das, was sie vormals nicht gekannt haben -',
        3: 'die fünf Philisterfürsten, alle Kanaaniter, Sidonier und die Chiwiter, die auf dem Libanongebirge vom Berge Baal Hermon bis gegen Hamat saßen.',
        4: 'Sie waren da, um Israel an ihnen zu prüfen und zu erfahren, ob sie des Herrn Gebot gehorchten, das er ihren Vätern durch Moses gegeben hatte.',
        5: 'So saßen die Israeliten mitten unter den Kanaanitern, Chittitern, Amoritern, Perizitern, Chiwitern und Jebusitern.',
        6: 'Sie nahmen sich ihre Töchter zu Weibern, und ihre Töchter gaben sie ihren Söhnen und dienten ihren Göttern.',
        7: 'Die Israeliten nun taten, was dem Herrn mißfiel, vergaßen des Herrn und dienten den Baalen und den Ascheren.',
        8: 'Da entbrannte des Herrn Zorn gegen Israel, und er verkaufte sie in die Hand des Kuschan Rischataim, des Königs von Mesopotamien. Und so dienten die Israeliten dem Kuschan Rischataim acht Jahre.',
        9: 'Da schrien die Israeliten zum Herrn, und der Herr ließ den Israeliten einen Retter erstehen, der sie befreite, Otniel, des Kenaz Sohn, Kalebs jüngeren Bruder.',
        10: 'Der Geist des Herrn kam auf ihn, und so richtete er Israel. Er zog zu Felde, und der Herr gab Arams König, Kuschan Rischataim, in seine Hand. Seine Hand lag schwer auf Kuschan Rischataim.',
        11: 'So rastete das Land vierzig Jahre. Da starb des Kenaz Sohn Otniel.',
        12: 'Die Israeliten aber taten aufs neue, was dem Herrn mißfiel. Da gab der Herr dem Moabkönig Eglon Macht über Israel, weil sie getan, was dem Herrn mißfiel.',
        13: 'Und er verband sich mit den Ammonitern und mit Amalek. So zog er hin, schlug Israel, und sie besetzten die Palmenstadt.',
        14: 'Die Israeliten dienten dem König Moabs, Eglon, achtzehn Jahre.',
        15: 'Da schrien die Israeliten zum Herrn, und der Herr ließ ihnen einen Retter erstehen, Ehud, den Sohn Geras, den Benjaminiten, einen Linkshänder. Durch ihn sandten die Israeliten an Moabs König, Eglon, eine Spende.',
        16: 'Da machte sich Ehud ein Schwert, zweischneidig und eine Spanne lang. Er gürtete es unter seinem Gewand an seine rechte Seite.',
        17: 'So brachte er die Spende dem Eglon, Moabs König. Eglon aber war sehr beleibt. Er war eben von den Götzenbildern im Gilgal heimgekehrt.',
        18: 'Als er die Spende überreicht hatte, entließ er die Leute, die Träger der Spende.',
        19: 'Er sprach: "König! Ein geheimes Wort habe ich an dich." Da sprach dieser: "Still!" Darauf gingen alle fort, die ihn umstanden.',
        20: 'Ehud war nun an ihn herangetreten. Er aber saß in seinem kühlen Söller allein da. Ehud sprach nun: "Ich habe an dich ein Gotteswort." Da stand er vom Throne auf.',
        21: 'Ehud aber streckte seine Linke aus, nahm das Schwert von seiner rechten Hüfte und stach es ihm in den Leib.',
        22: 'Und er stieß nach der Klinge das Heft hinein, und das Fett umschloß die Klinge; denn er hatte das Schwert nicht aus seinem Leibe gezogen; dann verließ er den Flur.',
        23: 'Hierauf ging Ehud durch den Mittelbau, verschloß die Türen des Obergemachs hinter sich und riegelte ab.',
        24: 'Eben war er fortgegangen, da kamen seine (Eglons) Diener und fanden die Tür des Söllers verriegelt. Sie sprachen: "Er begießt wohl in der kühlen Kammer seine Füße."',
        25: 'So warteten sie endlos. Aber niemand öffnete die Tür des Söllers. Da holten sie den Schlüssel und schlossen auf. Ihr Herr lag tot am Boden.',
        26: 'Ehud aber war während ihres Wartens entkommen und hatte die Götzenbilder umgestürzt, dann entkam er in den Busch.',
        27: 'Wie er nun heimkam, stieß er auf dem Gebirge Ephraim in das Horn. Da stiegen mit ihm die Israeliten vorn Gebirge herab, er an ihrer Spitze.',
        28: 'Er sprach zu ihnen: "Folgt mir schnell! Denn der Herr gibt eure Feinde, Moab, in eure Hand." Da stiegen sie hinab, ihm nach, besetzten die Jordanfurten gegen Moab und ließen niemand hinüber.',
        29: 'Sie schlugen damals Moab, etwa zehntausend Mann, Lauter starke und streitbare Leute; und niemand entrann.',
        30: 'Damals ward Moab unter Israels Hand gebeugt, und das Land hatte achtzig Jahre Ruhe.',
        31: 'Nach ihm trat Anats Sohn, Samgar, auf. Er schlug die Philister, sechshundert Mann, mit einem Ochsenstecken. Auch er befreite Israel.',
    },
    4: {
        1: 'Und wieder taten die Israeliten, was dem Herrn mißfiel. Ehud aber war gestorben.',
        2: 'So verkaufte sie der Herr in die Hand des Königs von Kanaan, Jabin, der zu Chasor regierte. Sein Feldherr war Sisera, der zu Charoset Haggojim saß.',
        3: 'Da schrien die Israeliten zum Herrn. Denn er hatte neunhundert eiserne Wagen und bedrückte die Israeliten zwanzig Jahre gewaltig.',
        4: 'In jener Zeit richtete Lapidots Weib, die Prophetin Debora, Israel.',
        5: 'Sie saß unter der Bienenpalme zwischen Rama und Betel auf dem Gebirge Ephraim, und die Israeliten zogen zum Gericht zu ihr hinauf.',
        6: 'Sie sandte nun hin und berief Abinoams Sohn, Barak, aus Kedes Naphtali. Sie sprach zu ihm: "Befiehlt nicht der Herr, Israels Gott? Auf! Zieh auf den Taborberg! Nimm mit dir zehntausend Mann aus Naphtalis und Zabulons Söhnen!',
        7: 'Dann locke ich zu dir an den Kisonbach Sisera, Jabins Heerführer, samt seinen Wagen und seinem Heereshaufen und gebe sie in deine Hand."',
        8: 'Barak aber sprach zu ihr: "Gehst du mit mir, dann gehe ich. Wenn nicht, dann gehe ich auch nicht."',
        9: 'Sie sprach: "Ich ziehe mit dir. Doch wird der Ruhm nicht dein werden auf dem Weg, den du gehst. Denn der Herr verkauft dann in eines Weibes Hand den Sisera." Darauf erhob sich Debora und zog mit Barak nach Kedes.',
        10: 'Barak entbot nun Zabulon und Naphtali nach Kedes. Zehntausend Mann folgten ihm auf dem Fuße hinauf. Auch Debora zog mit ihm hinauf.',
        11: 'Der Keniter Cheber aber hatte sich getrennt von Kain, einem der Söhne Chobabs, des Schwiegervaters Mosis, und zeltete an der Eiche zu Saanim bei Kedes.',
        12: 'Nun meldete man Sisera, Barak, Abinoams Sohn, sei auf den Berg Tabor gezogen.',
        13: 'Da entbot Sisera alle seine Wagen, neunhundert eiserne Wagen und das gesamte Kriegsvolk bei sich aus Charoset Haggojim an den Kisonbach.',
        14: 'Da sprach Debora zu Barak: "Auf! Das ist der Tag, in dem der Herr den Sisera in deine Hand gibt. Zieht der Herr nicht vor dir her?" Da stieg Barak vom Taborberge herab, und zehntausend Mann hinter ihm her.',
        15: 'Da verwirrte der Herr den Sisera, alle Wagen und das ganze Heer durch des Schwertes Schärfe vor Barak. Und Sisera stieg vom Wagen und floh zu Fuß.',
        16: 'Barak aber jagte den Wagen und das Heer bis Charoset Haggojim, und Siseras ganzes Heer fiel durch des Schwertes Schärfe. Auch nicht einer blieb übrig.',
        17: 'Sisera aber floh zu Fuß zum Zelte Jaëls, der Frau des Keniters Cheber. Denn zwischen Chasors König, Jabin, und dem Haus des Keniters Cheber war Frieden.',
        18: 'Da trat Jaël heraus, dem Sisera entgegen und sprach zu ihm: "Kehr ein, Herr! Kehre bei mir ein! Fürchte dich nicht!" Da kehrte er im Zelt bei ihr ein, und sie bedeckte ihn mit einer Decke.',
        19: 'Er sprach zu ihr: "Gib mir ein wenig Wasser! Mich dürstet." Da öffnete sie den Milchschlauch und ließ ihn trinken. Dann bedeckte sie ihn wieder.',
        20: 'Er aber sprach zu ihr: "Stell dich an des Zeltes Eingang! Kommt jemand und fragt dich und spricht: \'Ist jemand hier?\' so sag: \'Nein!\'"',
        21: 'Jaël, Chebers Weib, aber ergriff einen Zeltpflock, nahm den Hammer in die Hand und trat leise zu ihm; dann schlug sie ihm den Pflock durch die Schläfe, daß er in die Erde drang. Jener war nämlich eingeschlafen. Da zuckte er und starb.',
        22: 'Da kommt Barak, der Sisera nachjagt. Jaël tritt heraus, ihm entgegen, und spricht zu ihm: "Komm! Ich zeige dir den Mann, den du suchst." Er trat bei ihr ein. Da lag Sisera tot da, mit dem Zeltpflock in der Schläfe.',
        23: 'So demütigte Gott an jenem Tage Kanaans König, Jabin, vor den Israeliten.',
        24: 'Und die Hand der Israeliten wuchtete immer schwerer auf Jabin, Kanaans König, bis sie Kanaans König, Jabin, vernichtet hatten.',
    },
    5: {
        1: 'Da sang Debora mit Abinoams Sohn, Barak, an jenem Tage also:',
        2: '"Stimmt an in Israel, ihr Führer! Fall ein, du Volk, beim Loblied auf den Herrn!',
        3: 'Ihr Könige, hört! Horcht auf, ihr Herren! Ich bin des Herrn; ich will lobsingen; ich weih dem Herrn, dem Gotte Israels, ein Lied.',
        4: 'Herr! Als Du ausgezogen von Seïr, als Du von Edoms Fluren hergekommen, da zitterte die Erde, und die Himmel troffen; von Wasser troffen Wolken.',
        5: 'Vorm Herrn, dem Herrn, die Berge bebten, vorm Herrn, vor Israels Gott, am Sinai.',
        6: 'Gefeiert haben Straßen zur Zeit des Anatsohnes Samgar, in Jaëls Tagen. Denn die, die sonstens auf den Straßen zogen, betraten jetzt nur Seitenpfade.',
        7: 'In Israel gemangelt haben Schwerter, ja gemangelt, bis daß du aufgestanden bist, Debora, bis daß du dich in Israel erhoben hast als Mutter.',
        8: 'Dies wählte neue Führer, die sich damals einten. Schild aber sah man nicht, noch Speer bei vierzigtausend Mann in Israel.',
        9: 'Die Hochgemuten bei den Führern Israels, die sich dem Volke hingegeben, sie hatten hoch den Herrn gepriesen.',
        10: 'Die ihr auf weißen Eselinnen rittet, die auf den Wagen fuhren, die auf dem Weg marschierten,',
        11: 'sie stießen Rufe aus, anstimmend den Gebetsgesang: Des Herren Siegestaten priesen sie, die Siegestaten seines Schwertes in Israel! Dann zogen sie herab mit Planken, das Volk des Herrn.',
        12: "'Auf! Auf, Debora! Auf! Auf! Stimm an das Lied!' 'Auf, Barak! Gefangene mach dir, du Sohn des Abinoam!'",
        13: 'Voll Kraft stieg da herab die kleine Schar. Das Volk des Herrn griff an voll Wut, ganz eng vereint.',
        14: 'Ephraims Stamm zog aus in Kühnheit, und hinter ihm mit seinen Leuten Benjamin. Auszog Makir; herab die Edlen stiegen. Hinzogen die aus Zabulon Gemusterten.',
        15: 'Und bei Debora blieben Issakars Anführer, und unter Barak stellt sich Issakar und wird zu Tal gesandt mit seinen Truppen. In Rubens Sippen waren Große bitteren Gemütes.',
        16: "'Was bleibst du unschlüssig da sitzen? Um der Gemeinen Hohn zu hören?' In Rubens Sippen waren Große zornigen Gemütes.",
        17: "'Warum bleibt Gilead über dem Jordan? Warum weilt bei den Schiffen Dan? Bleibt Asser an dem Meeresufer sitzen, an seinen Buchten wohnen?'",
        18: 'Sein Leben hat das Volk von Zabulon bis in den Tod mißachtet, und Naphtali ward wild bis auf das äußerste.',
        19: 'Da kamen Könige und kämpften; da kämpften kampfesfroh die Könige von Kanaan zu Taanak an den Gewässern von Megiddo; doch sie errangen nicht den Silberpreis.',
        20: 'Vom Himmel kämpften, von ihren Bahnen kämpften selbst mit Sisera die Sterne.',
        21: 'Fort raffte sie der Kisonbach, der Kisonbach die Überraschten; des Frostes Kälte lähmte seine Starken.',
        22: 'Geschlagen hatten die zu Fuß die Reiterei, verjagt die Führer der Rossewagen.',
        23: "'Verfluchet, die bei Seite sind gestanden!' spricht des Herren Bote 'verfluchet, die zu ihnen hielten! Gekommen sind sie nimmer zu den Vorkämpfern des Herrn, zu des Herren Vorkämpfern mit Kriegern.'",
        24: 'Gesegnet sei die Jaël vor den Weibern des Cheber, des Keniters Weib! Sie sei im Zelt gesegnet vor den Weibern!',
        25: 'Um Wasser bittet er. Sie spendet Milch; in einer Ehrenschale reicht sie Sahne.',
        26: 'Doch ihre Linke streckt sich nach dem Pflock, und ihre Rechte nach dem Schmiedehammer. Sie hämmerte auf Sisera, durchschlug sein Haupt, zerschmetterte durchbohrend seine Schläfe.',
        27: 'Zu ihren Füßen sank er hin, fiel nieder und blieb liegen. Zu ihren Füßen sank er nochmals hin und stürzte nieder; wo er zusammenbrach, da blieb er liegen, hingestreckt.',
        28: "Durchs Fenster lehnte sich die Mutter Siseras und rief durchs Gitter: 'Warum enttäuscht sein Wagen mit der Heimkehr? Warum verziehn sich der Gespanne Tritte?'",
        29: 'Die Klügste ihrer Fürstinnen gab ihr zur Antwort; sie war es auch, die ihr erwiderte.',
        30: "'Sie fanden sicher Beute und verteilten sie, ein doppelt Maß für jeden Krieger; Beute mancher Art hat Sisera, Beute, mannigfaltig, prächtig; mannigfaltig, zierlich, herrlich ist die Beute.'",
        31: '\'So müssen alle, die dem Herren feind, zugrunde gehen! Doch die ihn lieben, sie gleichen einem Sonnenaufgange in seiner Pracht.\'" - Und das Land hatte vierzig Jahre Ruhe.',
    },
    6: {
        1: 'Die Israeliten aber taten wieder, was dem Herrn mißfiel. Da gab sie der Herr für sieben Jahre in die Hand Midians.',
        2: 'Und Midians Hand wuchtete auf Israel. Da benützten Midians wegen die Israeliten die Schluchten, Höhlen und Festen im Gebirge.',
        3: 'Wenn Israel gesät hatte, dann zogen die Midianiter, wie sonst Amalek und des Ostens Söhne, herauf und zogen dawider.',
        4: 'Sie lagerten wider sie und grasten des Landes junge Saat ab, bis Gaza hin. Sie ließen in Israel kein Futter übrig für Schafe, Rinder und Esel.',
        5: 'Denn sie kamen mit ihrem Vieh und brachten ihre Zelte mit. Sie kamen wie die Heuschrecken an Menge. Ihrer und ihrer Kamele war keine Zahl. So kamen sie in das Land, es abzugrasen.',
        6: 'Da verkümmerte Israel gewaltig durch Midian. So schrien die Israeliten zum Herrn.',
        7: 'So kam es, daß die Israeliten wegen Midian zum Herrn schrien.',
        8: 'Und der Herr sandte zu den Israeliten einen Propheten. Er sprach zu ihnen: "So spricht der Herr, Israels Gott: \'Ich habe euch aus Ägypten hergebracht und euch aus dem Sklavenhause geführt.',
        9: 'Ich befreite euch aus Ägyptens Hand und aus der Hand eurer Dränger. Ich vertrieb sie vor euch und gab euch ihr Land.',
        10: 'Ich sprach zu euch: "Ich bin der Herr, euer Gott. Ihr sollt nicht die Götter der Amoriter fürchten, in deren Land ihr siedelt!" Ihr aber habt nicht auf meine Stimme gehört.\'"',
        11: 'Da kam des Herrn Engel und setzte sich unter die Terebinthe zu Ophra, das dem Abiezriter Joas gehörte. Sein Sohn Gideon drosch eben in der Kelter Weizen, um ihn vor Midian zu bergen.',
        12: 'Da erschien ihm des Herrn Engel und sprach zu ihm: "Du tapferer Held! Der Herr ist mit dir."',
        13: 'Da sprach Gideon zu ihm: "Mit Vergunst, mein Herr! Ist der Herr mit uns, warum trifft uns all dies? Wo bleiben all seine Wundertaten, von denen unsere Väter uns also erzählt: Hat uns nicht der Herr aus Ägypten heraufgeführt? Aber jetzt verstößt uns der Herr und gibt uns in Midians Faust."',
        14: 'Da wandte sich der Herr ihm zu und sprach: "Geh in dieser deiner Kraft! Rette Israel aus Midians Hand! Sende ich dich nicht?"',
        15: 'Er sprach zu ihm: "Mit Vergunst, mein Herr! Womit soll ich Israel retten? Ist doch meine Sippe die schwächste in Manasse, und bin doch ich der geringste in meines Vaters Haus."',
        16: 'Da sprach der Herr zu ihm: "Bin ich mit dir, dann schlägst du Midian wie einen Mann."',
        17: 'Er sprach zu ihm: "Habe ich in Deinen Augen Gnade gefunden, so gib mir ein Zeichen, daß Du mit mir redest!',
        18: 'Weiche nicht von hier, bis ich zu Dir komme, meine Gabe hole und Dir vorsetzen Er sprach: "Ich bleibe, bis du wiederkommst."',
        19: 'Da ging Gideon weg und bereitete ein Ziegenböckchen und einen ungesäuerten Kuchen von einem Maß Mehl. Das Fleisch aber hatte er in den Korb gelegt und die Brühe in den Topf getan. So brachte er es ihm unter die Terebinthe und setzte es vor.',
        20: 'Da sprach zu ihm der Engel Gottes: "Nimm das Fleisch und die ungesäuerten Brote! Und lege sie drüben auf den Felsen! Die Brühe aber gieße weg!" Und er tat so.',
        21: 'Da streckte der Engel des Herrn die Spitze des Stabes in seiner Hand aus und berührte das Fleisch samt den ungesäuerten Broten. Da schlug Feuer aus dem Felsen und verzehrte das Fleisch samt den ungesäuerten Broten. Des Herrn Engel aber entschwand aus seinen Augen.',
        22: 'Da merkte Gideon, daß es der Engel des Herrn war. Und Gideon sprach: "Wehe, Herr, Herr! Leider habe ich des Herrn Engel von Angesicht zu Angesicht gesehen."',
        23: 'Da sprach der Herr zu ihm: "Friede sei mit dir! Fürchte dich nicht! Du wirst nicht sterben."',
        24: 'Da baute Gideon dort einen Altar dem Herrn und nannte ihn: "Des Herren Heil." Bis auf diesen Tag steht er noch im abiezritischen Ophra.',
        25: 'In jener Nacht sprach der Herr zu ihm: "Nimm deines Vaters Leitbullen, den zweigehörnten Stier von sieben Jahren, und zertrümmere den Baalsaltar deines Vaters! Die Aschera (hl. Pfahl) daneben aber sollst du fällen!',
        26: 'Dann baue einen Altar dem Herrn, deinem Gott, auf dieses Felsens Höhe mit einem Feuerherd und nimm den zweigehörnten Stier und bringe ihn als Brandopfer dar mit dem Holz des heiligen Pfahles, das du zerschlagen sollst!"',
        27: 'Da nahm Gideon aus seinen Sklaven zehn Männer und tat, wie ihm der Herr geboten. Weil er sich aber vor seines Vaters Haus und den Leuten der Stadt fürchtete, es bei Tag zu tun, so tat er es bei Nacht.',
        28: 'Als nun die Leute der Stadt am anderen Morgen aufstanden, war der Baalsaltar niedergerissen und der heilige Pfahl daneben umgehauen, und der zweigehörnte Stier geopfert auf dem neuerbauten Altar.',
        29: 'Die Leute fragten einander: "Wer hat dies getan?" Als sie so fragten und forschten, hieß es: "Des Joas Sohn Gideon hat dies getan."',
        30: 'Da sprachen die Leute der Stadt zu Joas: "Gib deinen Sohn heraus, daß er sterbe. Denn er hat den Baalsaltar eingerissen und den heiligen Pfahl daneben umgehauen."',
        31: 'Da sprach Joas zu all den Umstehenden: "Wollt ihr für den Baal streiten? Wollt ihr ihm helfen? Wer für ihn streitet, soll bis zum Morgen getötet werden! Ist er ein Gott, so streite er für sich selbst, weil man seinen Altar eingerissen hat!"',
        32: "So nannte man ihn an jenem Tag Jerubbaal, weil man sagte: 'Der Baal streite mit ihm, weil er seinen Altar eingerissen hat!'",
        33: 'Nun hatte sich ganz Midian, wie sonst Amalek und des Ostens Söhne, verbündet, war herübergekommen und lagerte in der Jezreelebene.',
        34: 'Da fuhr der Geist des Herrn in Gideon. Und er stieß in das Horn. So ward Abiezer zur Heeresfolge aufgerufen.',
        35: 'Danach sandte er Boten zu ganz Manasse. Auch dies ward zur Heeresfolge aufgerufen. Dann sandte er Boten nach Asser, Zabulon und Naphtali. Auch diese zogen ihnen entgegen.',
        36: 'Da sprach Gideon zu Gott: "Willst Du wirklich durch meine Hand die Israeliten retten, wie Du gesagt,',
        37: 'dann lege ich ein Schafvließ auf die Tenne. Ist der Tau allein auf dem Vließ und sonst überall der Boden trocken, dann weiß ich, daß Du durch meine Hand Israel rettest, wie Du gesagt."',
        38: 'Und so geschah es. Als er am anderen Morgen das Vließ auswand, preßte er aus dem Vließ Tau, eine Schale voll Wasser.',
        39: 'Da sprach Gideon zu Gott: "Ach! Möge nicht Dein Zorn über mich entflammen, wenn ich nur diesmal noch rede! Ich möchte es nur noch diesmal mit dem Vließ versuchen. Das Vließ allein bleibe trocken; aber sonst sei überall Tau auf dem Boden!"',
        40: 'Und Gott tat so in jener Nacht. Das Vließ allein blieb trocken; sonst aber lag überall auf dem Boden Tau.',
    },
    7: {
        1: 'Jerubbaal, das ist Gideon, machte sich nun früh auf mit allem Volke bei ihm, und sie lagerten bei der Quelle Charod, Midians Lager aber war nördlich davon, von dem Hügel des Maulbeerbaumes bis in die Ebene.',
        2: 'Da sprach der Herr zu Gideon: "Zuviel ist des Volkes bei dir, als daß ich Midian in deine Hand gäbe. Sonst könnte sich Israel wider mich brüsten und sagen: \'Ich habe mir selbst geholfen.\'',
        3: "So ruf denn laut zum Volke: 'Wer bangt und bebt, kehre um und schleiche vom Gileadgebirge fort!' Da kehrten vom Volke zweiundzwanzigtausend um; nur zehntausend blieben zurück.",
        4: 'Da sprach der Herr zu Gideon: "Noch ist es des Volkes zuviel. Führe sie zum Wasser, daß ich sie dir dort sichte! Von wem ich dir sage: \'Er begleite dich!\', der soll dich begleiten! Von wem ich aber zu dir sage: \'Er begleite dich nicht!\', der darf nicht mitziehen."',
        5: 'Da führte er das Volk ans Wasser, und der Herr sprach zu Gideon: "Wer mit der Zunge Wasser schlürft, wie die Hunde schlürfen, den stelle besonders! Ebenso jeden, der zum Trinken niederkniet!"',
        6: 'Da war die Zahl derer, die das Wasser mit dem Munde aus der Hand schlürften, dreihundert. Der ganze Rest des Volkes aber war zum Wassertrinken hingekniet.',
        7: 'Da sprach der Herr zu Gideon: "Mit den dreihundert Mann, die Wasser schlürften, rette ich euch und gebe Midian in deine Hand. All das andere Volk soll heimgehen, jeglicher an seinen Ort!"',
        8: 'Da bekamen sie des Volkes Vorrat in ihre Hand und seine Hörner. Dann entließ er alle Israeliten, jeden in seine Heimat; nur die dreihundert Mann hatte er behalten. Midians Lager aber war unter ihm in der Ebene.',
        9: 'In jener Nacht sprach der Herr zu ihm: "Auf! Steige hinab ins Lager! Ich gebe es in deine Hand.',
        10: 'Hast du aber Angst hinabzusteigen, so steige mit deinem Diener Pura zum Lager hinab!',
        11: 'Belausche, was sie darin sprechen! Dann werden deine Hände stark, und du wirst das Lager angreifen." Da stieg er mit seinem Diener Pura hinab bis ganz nahe an die Gewappneten im Lager.',
        12: 'Midian aber, wie sonst Amalek und alle Söhne des Ostens, lag in der Ebene wie Heuschrecken an Masse, und ihre Kamele waren zahllos wie die Sandmenge am Meeresufer.',
        13: 'Und Gideon kam. Da erzählte eben ein Mann dem anderen einen Traum und sprach: "Ich habe geträumt: Ein Stück Gerstenbrot rollte in Midians Lager, kam bis zum Zelt, traf es, daß es fiel, und drehte es nach oben, als das Zelt umfiel."',
        14: 'Da antwortete der andere und sprach: "Das ist nichts anderes, als des Joassohnes Gideon Schwert. Gott gibt einem Israeliten Midian mit dem ganzen Lager in seine Hand."',
        15: 'Als aber Gideon die Erzählung und die Auslegung des Traumes hörte, warf er sich anbetend nieder; dann kehrte er in Israels Lager zurück und sprach: "Auf! Der Herr gibt Midians Lager in eure Hand."',
        16: 'Darauf teilte er die dreihundert Mann in drei Heerhaufen und gab allen Hörner und leere Krüge in die Hand. In den Krügen aber waren Fackeln.',
        17: 'Dann sprach er zu ihnen: "Seht auf mich und tut ebenso! Komme ich bis zum Rande des Lagers, dann tut das gleiche, was ich tue!',
        18: 'Stoße ich in das Horn und alle bei mir, dann stoßt auch ihr in die Hörner um das Lager und ruft: \'Für den Herrn und Gideon!\'"',
        19: 'So kam Gideon mit den hundert Mann, die bei ihm waren, bis zum Lagerrand bei Beginn der mittleren Nachtwache. Eben hatten sie die Wachen ausgestellt. Da stießen sie in die Hörner und zerschlugen die Krüge in ihrer Hand.',
        20: 'So stießen die drei Heerhaufen in die Hörner, zerbrachen die Krüge, nahmen die Fackeln in die linke und die Hörner zum Blasen in die rechte Hand und riefen durchdringend: "Für den Herrn und Gideon!"',
        21: 'Dabei blieb jeder auf seinem Platze rings um das Lager. Im Lager aber rannte alles hin und her. Sie lärmten und flohen.',
        22: 'Jene aber stießen in die dreihundert Hörner, und der Herr wandte des einen Schwert gegen den anderen. Was im Lager war, floh bis nach Bet Sitta gegen Zereda hin, bis an das Ufer von Abel Mechola bei Tabbat.',
        23: 'Da ward Israels Mannschaft aus Naphtali, Asser und ganz Manasse aufgeboten, und sie verfolgten Midian.',
        24: 'Auch sandte Gideon Boten auf das ganze Gebirge Ephraim und ließ sagen: "Zieht hinab Midian entgegen und besetzt ihre Wasserstellen bis Bet Bara und bis an den Jordan!" Da ward Ephraims gesamte Mannschaft aufgeboten, und sie besetzten die Wasserstellen bis Bet Bara und an den Jordan.',
        25: 'Und sie fingen zwei Midianiterfürsten, Oreb und Zeeb. Den Oreb erschlugen sie am Rabenfelsen und den Zeeb bei der Wolfskelter. Dann jagten sie weiter Midian nach. Orebs und Zeebs Köpfe aber brachten sie zu Gideon über den Jordan.',
    },
    8: {
        1: 'Da sprach Ephraims Mannschaft zu ihm: "Was hast du uns angetan, daß du uns nicht riefst, als du in den Kampf wider Midian gezogen bist?", Und sie machten ihm heftige Vorwürfe.',
        2: 'Er sprach zu ihnen: "Was habe ich im Vergleich zu euch getan? Ist nicht Ephraims Nachlese besser als Abiezers Lese?',
        3: 'In eure Hand hat Gott die Midianiterfürsten Oreb und Zeeb gegeben. Was habe ich im Vergleich mit euch tun können?" Da legte sich ihr Zorn gegen ihn, als er so sprach.',
        4: 'Dann zog Gideon an den Jordan. Er und die dreihundert Mann bei ihm zogen hinüber. Sie waren zwar matt, setzten aber die Verfolgung fort.',
        5: 'Da sprach er zu Sukkots Männern: "Gebt den Leuten, die ich befehlige, Brotkuchen! Denn sie sind matt. Ich aber jage den Midianiterkönigen Zebach und Salmunna nach."',
        6: 'Da sagten Sukkots Oberste: "Hast du schon Zebach und Salmunna in deiner Hand, daß wir deiner Heerschar Brot geben sollten?"',
        7: 'Da sprach Gideon: "Nun gut! Gibt der Herr Zebach und Salmunna in meine Hand, dann zerdresche ich euch mit Wüstendornen und Disteln."',
        8: 'Von da zog er nach Penuel hinauf und sprach zu diesem ebenso. Aber Penuels Männer erwiderten ihm, wie die Männer Sukkots erwidert hatten.',
        9: 'Da sprach er zu Penuels Männern: "Komme ich heil zurück, dann schleife ich diesen Turm."',
        10: 'Zebach und Salmunna aber waren in Karkor mit ihrem Heer, etwa fünfzehntausend Mann. Das war alles, was vom ganzen Heer der Söhne des Ostens übriggeblieben war. Der Gefallenen waren es 120.000 Mann Schwertgerüstete.',
        11: 'Gideon zog nun den Weg gegen die Zeltleute östlich von Nobach und Jogbeha und überfiel das Lager; das Lager aber lag sorglos da.',
        12: 'Zebach und Salmunna flohen. Er aber jagte ihnen nach, fing die beiden Midianskönige Zebach und Salmunna und vernichtete das ganze Lager.',
        13: 'Hierauf kehrte Gideon, des Joas Sohn, an der Sonnensteige vom Kriegszug um.',
        14: 'Da griff er einen jungen Mann aus Sukkots Männern und fragte ihn aus. Und er schrieb ihm Sukkots Oberste und Älteste auf, siebenundsiebzig Mann.',
        15: 'So kam er zu den Männern von Sukkot und sprach: "Hier sind Zebach und Salmunna, deretwegen ihr mich gehöhnt habt mit den Worten: \'Hast du schon Zebach und Salmunna in deiner Hand, daß wir deinen hungrigen Männern Brot geben sollten?\'"',
        16: 'Dann nahm er die Ältesten der Stadt sowie Wüstendornen und Stacheln und verurteilte Sukkots Männer.',
        17: 'Ebenso schleifte er Penuels Turm und metzelte die Männer der Stadt nieder.',
        18: 'Dann sprach er zu Zebach und Salmunna: "Wie sind die Männer gewesen, die ihr am Tabor erschlagen habt?" Sie sprachen:"Ganz so wie du. Jeder nach Aussehen ein Königssohn."',
        19: 'Er sprach: "Das sind meine Brüder gewesen, meiner Mutter Söhne. So wahr der Herr lebt! Hättet ihr sie leben lassen, ich brächte euch nicht um."',
        20: 'Dann rief er seinen Erstgeborenen Jeter: "Auf! Schlag sie nieder!" Aber der Knabe zog sein Schwert nicht, weil er sich scheute. Denn er war noch zu jung.',
        21: 'Da sprachen Zebach und Salmunna: "Auf! Stoß du uns nieder! Denn wie der Mann, so seine Kraft!" Da stand Gideon auf und erschlug Zebach und Salmunna. Er nahm auch die kleinen Monde an den Hälsen ihrer Kamele.',
        22: 'Da sprach Israels Mannschaft zu Gideon: "Walte über uns, du, dein Sohn und dein Enkel! Denn du hast uns aus Midians Hand befreit."',
        23: 'Da sprach Gideon zu ihnen: "Weder will ich über euch walten, noch mein Sohn. Der Herr walte über euch!"',
        24: 'Dann sprach Gideon zu ihnen: "Ich will mir von euch etwas anderes erbitten: Gebt mir jeder aus seiner Beute einen Ring!" Jene hatten nämlich goldene Ringe, weil sie Ismaeliter waren.',
        25: 'Da sagten sie: "Gern geben wir dir sie." Und sie breiteten einen Mantel aus, und jeder warf seinen Beutering darauf.',
        26: 'Das Gewicht der Goldringe, die er erbeten hatte, betrug 1.700 Ring Gold, außer den Monden, Ohrgehängen und Purpurkleidern, die die Midianskönige getragen, und den Halsbändern ihrer Kamele.',
        27: 'Gideon machte daraus ein Ephod und stellte es in seiner Stadt Ophra auf. Und ganz Israel hurte ihm dort nach. So ward es Gideon und seinem Hause zum Fallstricke.',
        28: 'Also ward Midian von den Israeliten gedemütigt, daß es nicht wieder das Haupt erhob. Und das Land hatte in Gideons Tagen vierzig Jahre Ruhe.',
        29: 'Und Jerubbaal, des Joas Sohn, zog ab und blieb fortan zu Hause.',
        30: 'Gideon aber besaß siebzig Vollsöhne. Denn er hatte viele Weiber.',
        31: 'Sein Nebenweib zu Sichem aber hatte ihm auch einen Sohn geboren, und er legte ihm den Namen Abimelek bei.',
        32: 'Gideon, des Joas Sohn, starb in hohem Alter und ward in seines Vaters Joas Grab begraben, im Ophra der Abiezriten.',
        33: 'Als aber Gideon tot war, hurten die Israeliten wieder mit den Baalen. Sie nahmen sich den Bundesbaal zum Schutzgott.',
        34: 'Und die Israeliten gedachten nicht mehr des Herrn, ihres Gottes, der sie aus der Hand all ihrer Feinde ringsum befreit hatte.',
        35: 'Auch erwiesen sie keine Liebe der Familie Jerubbaals, vormals Gideon genannt, trotz dem Guten, das er Israel getan hatte.',
    },
    9: {
        1: 'Jerubbaals Sohn Abimelek nämlich ging nach Sichem zu den Brüdern seiner Mutter. Er sprach zu ihnen und zu der ganzen Sippe des Vaterhauses seiner Mutter also:',
        2: '"Befragt alle Sichemsbürger eindringlich: \'Was frommt euch mehr? Daß siebzig Männer über euch walten, all die Jerubbaalssöhne, oder nur ein Mann?\' Bedenkt auch, daß ich euer Fleisch und Bein bin!"',
        3: 'Da redeten die Brüder seiner Mutter seinetwegen eindringlich mit allen Bürgern von Sichem alle diese Worte. Da neigte sich ihr Sinn Abimelek zu; denn sie sagten: "Er ist unser Bruder."',
        4: 'Und sie gaben ihm siebzig Silberstücke aus dem Haus des Bundesbaal. Damit dingte Abimelek arme und gewissenlose Männer, die ihm folgten.',
        5: 'Dann ging er in seines Vaters Haus zu Ophra und erschlug seine Brüder, Jerubbaals Söhne, siebzig Mann, auf einem Steine. Nur Jerubbaals jüngster Sohn Jotam blieb übrig; denn er hatte sich versteckt.',
        6: 'Nun versammelten sich alle Bürger Sichems und das ganze Haus der Burg. Sie gingen hin und machten Abimelek zum König bei der Bildsäule, die in Sichem aufgestellt war.',
        7: 'Als man dies Jotam erzählte, ging er hin und stellte sich auf eine Höhe des Berges Garizim. Dann erhob er seine Stimme, rief und sprach zu ihnen: "Hört mich an, ihr Bürger von Sichem, auf daß euch Gott anhöre!',
        8: "Die Bäume sind darangegangen, zu salben einen König über sich. Sie sprachen zu dem Ölbaum: 'Sei du ein König über uns!'",
        9: "Der Ölbaum sprach zu ihnen: 'Habe ich mein Fett verloren, mit dem man Götter ehrt und Menschen, daß ich für die anderen Bäume zittern sollte?'",
        10: "So sprachen denn zum Feigenbaum die Bäume: 'Wohlan! Sei du ein König über uns!'",
        11: "Da sprach der Feigenbaum zu ihnen: 'Habe ich denn meine Süßigkeit verloren und meine edle Frucht, daß ich für die anderen Bäume zittern sollte?'",
        12: "Die Bäume sprachen zu dem Weinstock: 'Wohlan! Sei du ein König aber uns!'",
        13: "Der Weinstock sprach zu ihnen: 'Habe ich denn meinen Wein verloren, der fröhlich Götter macht und Menschen, daß ich für die anderen Bäume zittern sollte?'",
        14: "Da sprachen zu dem Stechdorn all die Bäume: 'Wohlan! Sei du ein König über uns!'",
        15: "Da sprach der Stechdorn zu den Bäumen: 'Wollt ihr im Ernst mich über euch zum König machen, dann kommt und berget euch in meinem Schatten! Wo nicht, dann gehe Feuer von dem Stechdorn aus, und dies verzehre auf dem Libanon die Zedern!'",
        16: 'Nun denn! Habt ihr ehrlich und redlich gehandelt, als ihr Abimelek zum König machtet? Habt ihr an Jerubbaal und seinem Hause schön gehandelt und ihm vergolten, was seine Hände für euch getan?',
        17: 'Ihr, für die mein Vater kämpfend sein Leben gewagt und die er aus Midians Hand gerettet hat?',
        18: 'Und ihr habt euch gegen meines Vaters Haus erhoben, seine Söhne, siebzig Mann, auf einem Stein ermordet und seiner Sklavin Sohn Abimelek zum König gemacht, ihr Bürger von Sichem, weil er euer Bruder sei.',
        19: 'Habt ihr also ehrlich und redlich an Jerubbaal und seinem Haus gehandelt, dann freut euch Abimeleks, und auch er freue sich eurer!',
        20: 'Wenn aber nicht, dann soll von Abimelek Feuer ausgehen und die Bürger Sichems verzehren und das Haus der Bastei! Und von den Bürgern Sichems und von dem Basteihause soll Feuer ausgehen und Abimelek verzehren!"',
        21: 'Hierauf entwich Jotam, floh und ging nach Beer. Dort saß er in Sicherheit vor seinem Bruder Abimelek.',
        22: 'Abimelek herrschte nun über Israel drei Jahre.',
        23: 'Da sandte Gott einen bösen Geist zwischen Abimelek und die Bürger Sichems, und die Bürger Sichems fielen treulos von Abimelek ab.',
        24: 'Dadurch sollte der Frevel an Jerubbaals siebzig Söhnen und ihr Blut über ihren Bruder Abimelek kommen, der sie ermordet hatte, ebenso auf Sichems Bürger, die ihm geholfen hatten, seine Brüder zu ermorden.',
        25: 'Die Bürger Sichems stellten jetzt auf der Berge Höhen Wegelagerer auf, und diese plünderten jeden, der an ihnen vorüberzog. Dies ward Abimelek gemeldet.',
        26: 'Da kam Gaal, Ebeds Sohn, mit seinen Brüdern und ließ sich in Sichem nieder. Auf ihn verließen sich nun Sichems Bürger.',
        27: 'Sie gingen auf das Feld hinaus, hielten in ihren Weinbergen Lese und kelterten. Dann feierten sie ein Dankfest, gingen in ihres Gottes Haus, aßen und tranken und lästerten Abimelek.',
        28: 'Und Gaal, Ebeds Sohn, sprach: "Wer ist Abimelek und was ist Sichem, daß wir ihm dienen sollen? Sollten nicht Jerubbaals Sohn und sein Statthalter Zebul den Männern Chamors, des Vaters von Sichem, dienen? Warum sollten wir ihm dienen?',
        29: 'Gäbe nur einer dieses Volk in meine Hand, dann wollte ich Abimelek absetzen! Man würde zu Abimelek sagen: \'Dein Dienst hat lange genug gedauert. Nun geh fort!\'"',
        30: 'Der Befehlshaber der Stadt, Zebul, aber hörte von den Reden Gaals, des Ebedsohnes, und ergrimmte darüber:',
        31: 'Er sandte heimlich Boten an Abimelek und ließ sagen: "Gaal, Ebeds Sohn, ist mit seinen Brüdern nach Sichem gekommen. Nun wiegeln sie die Stadt wider dich auf.',
        32: 'Mach dich also bei Nacht auf, du und das Kriegsvolk bei dir, und lege dich im Feld in einen Hinterhalt!',
        33: 'Am Morgen, wenn die Sonne aufgeht, brich auf und überfalle die Stadt! Rückt er dann mit dem Kriegsvolk bei ihm gegen dich, dann tu mit ihm, wie du es vermagst!"',
        34: 'Da machte sich Abimelek mit dem ganzen Kriegsvolk bei ihm des Nachts auf, und sie legten sich in vier Scharen gegen Sichem in den Hinterhalt.',
        35: 'Nun kam Gaal, Ebeds Sohn, heraus und stellte sich an den Eingang des Stadttores. Da brach Abimelek mit dem Kriegsvolk bei ihm aus dem Hinterhalt auf.',
        36: 'Gaal sah das Kriegsvolk. Da sprach er zu Zebul: "Kriegsvolk kommt von der Berge Höhen." Zebul sprach zu ihm: "Du siehst der Berge Schatten für Männer an."',
        37: 'Gaal hob noch einmal an und sprach: "Fürwahr! Kriegsvolk steigt von des Landes Mitte. Eine Schar kommt von der Zauberereiche."',
        38: 'Da sprach Zebul zu ihm: "Wo ist jetzt dein Maul, daß du sprachst: \'Wer ist Abimelek daß wir ihm dienen sollen?\' Ist das nicht das Kriegsvolk, das du verachtet hast? Rück doch jetzt aus und streit mit ihm!"',
        39: 'Da zog Gaal an der Spitze der Bürger von Sichem aus und stritt wider Abimelek.',
        40: 'Abimelek aber verfolgte ihn, und er floh vor ihm, und viele Erschlagene fielen bis vor das Stadttor.',
        41: 'Dann kehrte Abimelek nach Aruma zurück. Zebul aber vertrieb den Gaal mit seinen Brüdern, daß für sie in Sichem keines Bleibens war.',
        42: 'Am anderen Morgen ging das Volk ins Freie. Dies meldete man Abimelek.',
        43: 'Da nahm er das Kriegsvolk, teilte es in drei Scharen und legte sich im Freien in den Hinterhalt. Sobald er das Volk aus der Stadt kommen sah, rückte er gegen es und schlug es.',
        44: 'Abimelek war nämlich mit den Scharen bei ihm losgebrochen: Dann stellten sie sich vor das Stadttor; die beiden anderen Scharen aber hatten alle im Freien draußen überfallen, und so schlugen sie sie.',
        45: 'Abimelek aber berannte die Stadt jenen ganzen Tag. Schließlich eroberte er die Stadt. Nachdem er das Volk darin erschlagen, zerstörte er die Stadt und streute Salz darauf.',
        46: 'Dies hörten alle Bürger des Sichemturmes. Da gingen sie in den Söller im Hause des Bundesgottes.',
        47: "Das wurde Abimelek gemeldet: 'Alle Bürger des Sichemturmes sind beisammen.'",
        48: 'Da stieg Abimelek auf den Salmonberg mit dem ganzen Volke bei ihm. Hier nahm Abimelek die Axt in die Hand, hieb einen Busch ab, hob ihn auf und legte ihn auf die Schulter. Dann sprach er zu dem Volke bei ihm. "Was ihr mich tun sehet, macht mir schleunigst nach!"',
        49: 'Da hieb das ganze Volk, Mann für Mann, Büsche ab. Dann folgten sie Abimelek, warfen sie um den Söller und steckten über ihnen den Söller in Brand. So starben alle Insassen des Sichemturmes, an tausend Männer und Weiber.',
        50: 'Abimelek zog nun nach Tebes. Er belagerte Tebes und eroberte es.',
        51: 'Inmitten der Stadt aber war ein starker Turm. Dorthin flohen alle Männer und Weiber sowie alle Edlen der Stadt. Sie riegelten hinter sich zu und stiegen auf das Dach des Turmes.',
        52: 'Abimelek kam nun bis an den Turm und berannte ihn. Er trat an die Turmtür, sie in Brand zu stecken.',
        53: 'Da warf ein Weib einen oberen Mühlstein dem Abimelek auf den Kopf und zerschmetterte ihm den Schädel.',
        54: 'Da rief er eilends den Burschen, der seine Waffen trug, und sprach zu ihm: "Ziehe dein Schwert und töte mich, daß sie nicht von mir sagen: \'Ein Weib hat ihn umgebracht!\'" So durchbohrte ihn sein Bursche, und er starb.',
        55: 'Als Israels Mannschaft sah, daß Abimelek tot war, ging ein jeder heim.',
        56: 'So vergalt Gott Abimeleks Freveltat, die er an seinem Vater verübt hatte, als er seine siebzig Brüder erschlug.',
        57: 'Ebenso vergalt Gott alle Schlechtigkeit der Männer von Sichem auf ihr Haupt. So traf sie der Fluch des Jerubbaalsohnes Jotam.',
    },
    10: {
        1: 'Nach Abimelek kam zu Israels Rettung Tola, Puas Sohn und Dodus Enkel, aus Issakar. Er saß zu Samir auf dem Gebirge Ephraim.',
        2: 'Er richtete Israel 2',
        3: 'Jahre. Dann starb er und ward in Samir begraben. 3 Nach ihm kam der Gileadite Jair und richtete Israel 22 Jahre.',
        4: 'Er hatte dreißig Söhne, die auf dreißig Eselsfüllen ritten und dreißig Städte besaßen. Diese nennt man Jairs Zeltdörfer bis auf diesen Tag. Sie sind im Lande Gilead.',
        5: 'Jair starb und ward in Kanon begraben.',
        6: 'Und wieder taten die Israeliten, was dem Herrn mißfiel, und sie dienten den Baalen und Astarten und den Göttern Syriens, Sidons, Moabs und den Göttern der Ammoniter und der Philister. So verließen sie den Herrn und dienten ihm nicht mehr.',
        7: 'Da entbrannte des Herrn Zorn wider Israel, und er verkaufte sie in die Hand der Philister und der Ammoniter.',
        8: 'Und diese quälten und plagten die Israeliten zehn Jahre lang, alle Israeliten jenseits des Jordans im Amoriterlande, in Gilead.',
        9: 'Dann zogen die Ammoniter über den Jordan, um auch mit Juda, Benjamin und dem Hause Ephraim zu streiten. Und Israel kam in große Not.',
        10: 'Da schrien die Israeliten zum Herrn und sprachen: "Wir haben wider Dich gesündigt; denn wir haben in der Tat unseren Gott verlassen und den Baalen gedient."',
        11: 'Da sprach der Herr zu den Israeliten: "Haben nicht Leute der Ägypter und Amoriter, der Ammoniter und Philister,',
        12: 'Sidonier, Amalek und Maon euch bedrängt? Da schriet ihr zu mir, und ich befreite euch aus ihrer Hand.',
        13: 'Da verließet ihr mich und dientet anderen Göttern. Darum helfe ich euch nicht länger.',
        14: 'Geht und ruft zu den Göttern, die ihr erwählt habt! Sie mögen euch in euren Nöten helfen!"',
        15: 'Da sprachen die Israeliten zum Herrn: "Wir haben gesündigt. Tu mit uns, wie es Dir gefällt! Nur rette uns jetzt!"',
        16: 'Und sie schafften des Auslands Götter aus ihrer Mitte und dienten dem Herrn. Da ward er über Israels Elend ungeduldig.',
        17: 'Die Ammoniter aber wurden wieder aufgeboten und lagerten in Gilead. Da kamen auch die Israeliten zusammen und lagerten in der Mispa.',
        18: 'Da sprach das Volk in Gileads Städten zueinander: "Wer ist der Mann, der mit den Ammonitern zu streiten beginnt? Er soll das Haupt aller Insassen Gileads werden!"',
    },
    11: {
        1: 'Der Gileaditer Jephte nun war ein tapferer Held, aber Sohn eines Kebsweibes. Als Gilead den Jephte erzeugt hatte,',
        2: 'gebar Gileads Frau ihm gleichfalls Söhne. Herangewachsen, vertrieben die Söhne dieser Frau den Jephte. Sie sprachen zu ihm: "Du darfst in unseres Vaters Haus nicht miterben; denn du bist der Sohn eines anderen Weibes."',
        3: 'Da entwich Jephte vor seinen Brüdern und weilte im Lande Tob. Da scharten sich um Jephte arme Männer und zogen mit ihm aus.',
        4: 'Nach einiger Zeit stritten die Ammoniter mit Israel.',
        5: 'Als nun die Ammoniter mit Israel stritten, gingen die Ältesten Gileads hin, Jephte aus dem Lande Tob zu holen.',
        6: 'Sie sprachen zu Jephte: "Komm! Sei unser Anführer! Dann wollen wir gegen die Ammoniter streiten."',
        7: 'Da sprach Jephte zu Gileads Ältesten: "Habt ihr mich nicht gehaßt, so daß ihr mich aus meines Vaters Haus vertriebet? Warum kommt ihr jetzt zu mir, wo ihr in Not seid?"',
        8: 'Da sprachen Gileads Älteste zu Jephte: "Trotz alledem! Wir sind jetzt anderer Gesinnung gegen dich. Gehst du mit uns und streitest gegen die Ammoniter, dann sollst du uns Haupt sein, allen Insassen Gileads!"',
        9: 'Da sprach Jephte zu Gileads Ältesten: "Wenn ihr mich zurückholt, gegen die Ammoniter zu streiten, und der Herr gibt sie mir preis, werde ich dann euer Haupt?"',
        10: 'Die Ältesten Gileads sprachen zu Jephte: "Der Herr hört, was zwischen uns vorgeht; wir tun, wie du verlangst."',
        11: 'Da zog Jephte mit Gileads Ältesten, und das Volk machte ihn zum Haupt und Führer über sich. Jephte aber wiederholte all seine Forderungen vor dem Herrn auf der Mispa.',
        12: 'Dann sandte Jephte an den Ammoniterkönig Boten mit der Anfrage: "Was hast du mit mir, daß du zu mir kommst, in meinem Lande zu streiten?"',
        13: 'Da sprach der Ammoniterkönig zu Jephtes Boten: "Israel hat mein Land weggenommen vom Arnon bis zum Jabbok und Jordan, als es aus Ägypten zog. Gib es gutwillig zurück!"',
        14: 'Da sandte Jephte nochmals Boten an den Ammoniterkönig',
        15: 'und ließ ihm sagen: "So spricht Jephte: \'Israel hat das Land Moab und das Ammoniterland nicht weggenommen.',
        16: 'Als Israel aus Ägypten kam und in der Wüste zum Schilfmeer zog und nach Kades kam,',
        17: 'sandte Israel Boten an den Edomiterkönig mit der Bitte: " Ich möchte durch dein Land ziehen." Aber Edoms König gab ihm kein Gehör. Auch an Moabs König hatte es gesandt; aber auch er wollte nicht. So saß Israel in Kades.',
        18: 'Dann zog es durch die Wüste, umging das Land Edom und das Moabland und lagerte jenseits des Arnon. So haben sie kein Moabitergebiet betreten. Denn der Arnon ist Moabs Grenze.',
        19: 'Dann sandte Israel Boten an den Amoriterkönig Sichon, den König zu Chesbon. Israel sprach zu ihm: "Wir möchten durch dein Land an unsere Stätte ziehen."',
        20: 'Aber Sichon hatte Israels Durchzug durch sein Gebiet nicht getraut. Und so sammelte Sichon sein ganzes Volk. Und sie lagerten zu Jahsa. Dann stritt er mit Israel.',
        21: 'Aber der Herr, Israels Gott, gab Sichon mit seinem ganzen Volk in Israels Hand, und sie schlugen sie. So bekam Israel das ganze Land der Amoriter, die in diesem Lande saßen.',
        22: 'Sie besetzten das ganze Amoritergebiet vom Arnon bis zum Jabbok und von der Wüste bis zum Jordan.',
        23: 'Nun denn! Der Herr, Israels Gott, hat die Amoriter wegen seines Volkes Israel enteignet, und da willst du in ihren Besitz treten?',
        24: 'Nicht wahr! Wen dein Gott Kasmos enteignet, den verdrängst du. Wen also der Herr, unser Gott, unseretwegen enteignet, den verdrängen wir.',
        25: 'Nun, bist du viel stärker als Sippors Sohn, Balak, Moabs König? Hat er mit Israel gestritten oder mit ihm gekämpft?',
        26: 'Israel saß doch in Chesbon und seinen Tochterorten, in Aroër und den seinigen und in all den Städten am Arnon dreihundert Jahre. Warum habt ihr sie nicht in dieser Zeit entrissen?',
        27: 'Ich habe dir nichts zuleid getan. Du aber tust Unrecht, wenn du mich beschimpfst. Der Herr richte heute als Richter zwischen den Israeliten und den Ammonitern!\'"',
        28: 'Der Ammoniterkönig aber hörte nicht auf Jephtes Worte, die er ihm entboten hatte.',
        29: 'Da kam der Geist des Herrn über Jephte. Er zog nach Gilead und Manasse. Dann zog er nach Gileads Mispa; von Gileads Mispa aber zog er wider die Ammoniter.',
        30: 'Und Jephte tat dem Herrn ein Gelübde und sprach: "Gibst Du mir die Ammoniter in meine Hand,',
        31: 'dann sei das, was mir aus meines Hauses Tür entgegenkommt, des Herrn, falls ich heil von den Ammonitem kehre! Ich will es als Brandopfer darbringen."',
        32: 'So zog Jephte, wider die Ammoniter zu streiten. Und der Herr gab sie in seine Hand.',
        33: 'Er schlug sie ganz gewaltig, von Aroër bis gegen Minnit, zwanzig Städte, und bis Abel, zwanzig Städte. So wurden die Ammoniter vor den Israeliten gebeugt.',
        34: 'Jephte kehrte nach der Mispa zurück. Da kam ihm seine Tochter entgegen mit Pauken und im Reigentanz. Sie war gerade der Liebling. Für ihn gab es weder Sohn noch Tochter.',
        35: 'Als er sie sah, zerriß er seine Kleider und sprach. "Ach meine Tochter! Du beugst mich nieder. Du selbst bist unter meinen Unglücksbringern. Denn ich habe meinen Mund vor dem Herrn aufgetan. Ich kann nicht zurück."',
        36: 'Da sprach sie zu ihm: "Mein Vater! Hast du vor dem Herrn deinen Mund aufgetan, so tu an mir, wie es aus deinem Munde kam, nachdem der Herr dir Rache verschafft an deinen Feinden, den Ammonitern!"',
        37: 'Und sie sprach zu ihrem Vater: "Dies sei mir gewährt! Laß mir noch zwei Monate, daß ich hingehe und in den Bergen weile und mein Jungfrauenalter beweine, ich und meine Gespielinnen!"',
        38: 'Er sprach: "Geh hin!" Und er entließ sie für zwei Monate. Da ging sie mit ihren Gespielinnen und beweinte auf den Bergen ihr Jungfrauenalter.',
        39: 'Nach Verlauf zweier Monate kehrte sie zu ihrem Vater heim. Und er vollzog an ihr sein Gelübde, das er gelobt. Sie hatte noch keinen Mann erkannt. In Israel ward es Sitte,',
        40: 'daß alljährlich Israels Töchter hingingen, des Gileaditers Jephte Tochter jedes Jahr vier Tage zu beklagen.',
    },
    12: {
        1: 'Da ward Ephraims Mannschaft aufgeboten. Und sie zog gen Saphon. Und sie sprachen zu Jephte: "Warum bist du in den Kampf wider die Ammoniter gezogen und hast uns nicht gerufen, mit dir zu ziehen? Wir wollen dein Haus über dir anzünden."',
        2: 'Da sprach Jephte zu ihnen: "Ich und mein Volk haben einen schweren Kampf mit den Ammonitern gehabt. Ich rief euch; aber ihr habt mich nicht aus ihrer Hand befreit.',
        3: 'Als ich sah, daß du mir nicht halfest, da wagte ich mein Leben und zog aus gegen die Ammoniter. Und der Herr gab sie in meine Hand. Was zieht ihr heute wider mich, mit mir zu streiten?"',
        4: 'Dann bot Jephte alle Männer Gileads auf und stritt mit Ephraim. Da schlugen Gileads Männer Ephraim. Denn dieses pflegte zu sagen: "Ihr seid Flüchtlinge aus Ephraim." Gilead liegt ja zwischen Ephraim und Manasse.',
        5: 'Und Gilead besetzte die Jordanfurten nach Ephraim. Sagten nun die Flüchtlinge von Ephraim: "Ich möchte hinüber", so fragten ihn die Männer Gileads: "Bist du ein Ephratiter?" Sagte er: "Nein!"',
        6: 'Dann sagten sie zu ihm- "Sag doch Schibbolet! Sagte er Sibbolet, weil er nicht richtig sprechen konnte, dann griffen sie ihn und metzelten ihn an den Jordanfurten. So fielen damals aus Ephraim 42.000.',
        7: 'Und Jephte richtete Israel sechs Jahre. Dann starb Jephte, der Gileaditer, und ward in einer der Städte Gileads begraben.',
        8: 'Nach ihm richtete Ibsan aus Bethlehem Israel.',
        9: 'Er hatte dreißig Söhne. Dreißig Töchter gab er auswärts und dreißig Töchter führte er seinen Söhnen von auswärts zu. Er richtete Israel sieben Jahre.',
        10: 'Ibsan starb und ward zu Bethlehem begraben.',
        11: 'Nach ihm richtete der Zabulonite Elon Israel. Er richtete Israel zehn Jahre lang.',
        12: 'Dann starb der Zabulonite Elon und ward zu Ajjalon im Lande Zabulon begraben.',
        13: 'Nach ihm richtete der Piratonite Abdon, Hillels Sohn, Israel.',
        14: 'Er hatte vierzig Söhne und dreißig Enkel, die auf siebzig Eselsfüllen ritten. Er richtete Israel acht Jahre.',
        15: 'Dann starb der Piratonite Abdon, Hillels Sohn, und ward zu Piraton im Land Ephraim auf dem Arnalekitergebirge begraben.',
    },
    13: {
        1: 'Und wieder taten die Israeliten, was dem Herrn mißfiel. Und der Herr gab sie in der Philister Hand vierzig Jahre.',
        2: 'Da war ein Mann aus Sora, vom Geschlechte der Daniten, namens Manoach. Sein Weib aber war unfruchtbar und hatte nicht geboren.',
        3: 'Da erschien des Herrn Engel dem Weib und sprach zu ihr: "Du bist unfruchtbar und hast nicht geboren. Aber du sollst in Hoffnung kommen und einen Sohn gebären.',
        4: 'Dann nimm dich in acht! Trink weder Wein noch Bier und iß nichts Unreines!',
        5: 'Denn du kommst in Hoffnung und gebierst einen Sohn. Auf sein Haupt darf aber kein Schermesser kommen! Denn ein Gottgeweihter soll der Knabe schon im Mutterleibe sein. Er wird anfangen, Israel aus der Philister Hand zu befreien."',
        6: 'Da ging das Weib und erzählte ihrem Mann also: "Ein Gottesmann ist zu mir gekommen. Er war wie ein Engel Gottes, überaus ehrwürdig anzusehen. Ich habe ihn aber nicht gefragt, woher er sei. Auch er hat mir seinen Namen nicht genannt.',
        7: 'Er sagte aber zu mir: \'Du kommst in Hoffnung und gebierst einen Sohn. Trink jetzt weder Wein noch Bier und iß nichts Unreines! Denn ein Gottgeweihter wird der Knabe sein vom Mutterleibe bis zu seinem Todestage.\'"',
        8: 'Da betete Manoach zum Herrn und sprach: "Mit Vergunst, Herr! Der Gottesmann, den Du gesandt, möge nochmals zu uns kommen und uns belehren, was wir mit dem Knaben tun sollen, der geboren wird!"',
        9: 'Und Gott hörte auf Manoachs Stimme. Und so kam der Gottesengel nochmals zu dem Weibe. Sie weilte eben auf dem Felde. Ihr Mann Manoach war aber nicht bei ihr.',
        10: 'Eilends lief das Weib hin und meldete es ihrem Manne und sprach zu ihm: "Eben ist mir der Mann erschienen, der damals zu mir gekommen."',
        11: 'Da stand Manoach auf, folgte seinem Weibe, kam zu dem Mann und sprach zu ihm: "Bist du der Mann, der mit dem Weibe gesprochen?" Er sagte: "Ja!"',
        12: 'Da sprach Manoach: "Wenn deine Worte eintreffen, wie soll des Knaben Weise sein und wie sein Tun?"',
        13: 'Da sprach des Herrn Engel zu Manoach: "Vor all dem, was ich dem Weibe genannt, soll sie sich hüten!',
        14: 'Sie genieße gar nichts, was vom Weinstock kommt! Sie trinke weder Wein noch Bier, noch esse sie etwas Unreines! Alles, was ich ihr geboten, soll sie beobachten!"',
        15: 'Da sprach Manoach zu des Herrn Engel: "Wir möchten dich aufhalten und dir ein Ziegenböckchen vorsetzen."',
        16: 'Da sprach des Herrn Engel zu Manoach: "Wolltest du mich auch aufhalten ich koste doch nicht von deiner Speise. Willst du aber ein Brandopfer bereiten, dann bringe es dem Herrn dar!" Manoach nämlich wußte nicht, daß es des Herrn Engel war.',
        17: 'So fragte Manoach den Engel des Herrn: "Wie heißst du? Denn trifft dein Wort ein, möchten wir es dir lohnen."',
        18: 'Da sprach des Herrn Engel zu ihm: "Wozu fragst du nach meinem Namen? Ist es doch ein Wunder des Herrn."',
        19: 'Da nahm Manoach das Ziegenböckchen und das Speiseopfer und brachte es auf dem Felsen dem Herrn dar. Er aber tat Wunderbares. Manoach und sein Weib schauten zu.',
        20: 'Als die Flamme vom Altar zum Himmel stieg, fuhr des Herrn Engel in der Flamme auf. Manoach und sein Weib sahen es. Da fielen sie zur Erde auf ihr Angesicht.',
        21: 'Des Herrn Engel aber erschien Manoach und seinem Weibe nicht wieder. Da erkannte Manoach, daß es der Engel des Herrn war.',
        22: 'Und Manoach sprach zu seinem Weibe: "Wir müssen sterben; denn wir haben einen Gott gesehen."',
        23: 'Da sprach sein Weib zu ihm: "Hätte uns der Herr töten wollen, so hätte er nicht Brand- und Speiseopfer von uns angenommen und uns nicht jetzt solches schauen und hören lassen."',
        24: 'Und das Weib gebar einen Sohn. Sie hieß ihn Simson. Der Knabe wuchs heran, und der Herr segnete ihn.',
        25: 'Und der Geist des Herrn begann, ihn anzutreiben in Dans Lager zwischen Sora und Estaol.',
    },
    14: {
        1: 'Simson aber ging nach Timnat hinab und sah zu Timnat ein philistäisches Weib.',
        2: 'Da ging er hinauf und erzählte es Vater und Mutter. Er sprach: "Ich habe zu Timnat ein philistäisches Weib gesehen. Freit mir sie jetzt zum Weibe!"',
        3: 'Da sprachen zu ihm Vater und Mutter: "Gibt es unter den Töchtern deiner Brüder und in meinem ganzen Volke kein Weib, daß du bei den unbeschnittenen Philistern ein Weib freien willst?" Simson aber sprach zu seinem Vater: "Freie mir sie! Denn diese gefällt mir."',
        4: 'Sein Vater und seine Mutter aber wußten nicht, daß es vom Herrn kam, daß er einen Anlaß gegen die Philister suchte. Zu jener Zeit herrschten nämlich die Philister über Israel.',
        5: 'So ging Simson mit Vater und Mutter nach Timnat hinunter. Sie kamen zu den Weinbergen Timnats. Und da brüllte ihm ein junger Löwe entgegen.',
        6: 'Da kam der Geist des Herrn über ihn, und er schlitzte ihn auf, wie man ein Böckchen aufschlitzt. Er hatte dabei nichts in der Hand. Seinem Vater und seiner Mutter aber sagte er nicht, was er getan.',
        7: 'Dann ging er hinab und warb um das Weib, und sie gefiel Simson.',
        8: 'Nach einiger Zeit kam er wieder, sie heimzuholen. Da bog er ab, das Aas des Löwen zu schauen. Da war in dem Körper des Löwen,ein Bienenschwarm und Honig.',
        9: 'Er nahm diesen in seine Hände und aß im Gehen. Und als er zu Vater und Mutter kam, gab er ihnen davon, und sie aßen. Er verriet ihnen aber nicht, daß er den Honig aus dem Körper des Löwen geholt hatte.',
        10: 'Dann ging er selber wegen des Weibes hinab. Und Simson veranstaltete dort ein Gelage. Denn so machten es die jungen Leute.',
        11: 'Als sie ihn sahen, wählten sie dreißig Genossen aus, und diese blieben bei ihm.',
        12: 'Zu diesen sprach Simson: "Ich will euch ein Rätsel aufgeben. Löst ihr es mir in den sieben Tagen des Gelages, und findet ihr es, dann gebe ich euch dreißig Unterkleider und dreißig Festgewänder.',
        13: 'Könnt ihr es mir aber nicht lösen, dann gebt ihr mir dreißig Unterkleider und dreißig Festgewänder." Sie sprachen zu ihm: "Gib dein Rätsel auf, daß wir es vernehmen!"',
        14: 'Er sprach zu ihnen: "Fraß ist vom Fresser gekommen, Süßes vom Herben." Sie aber konnten während dreier Tage das Rätsel nicht lösen.',
        15: 'Am vierten Tage sprachen sie zu Simsons Weib: "Berede deinen Mann, daß er uns des Rätsels Lösung gibt! Sonst verbrennen wir dich und das Haus deines Vaters. Habt ihr uns nur eingeladen, um uns arm zu machen? Oder nicht?"',
        16: 'Da weinte Simsons Weib ihm vor und sprach: "Nicht anders ist\'s: Du bist mir abgeneigt. Du liebst mich nicht. Hast du nicht meinen Landsleuten ein Rätsel aufgegeben? Und mir sagst du es nicht." Er sprach zu ihr: "Weder Vater noch Mutter habe ich es verraten und dir sollt ich es verraten?"',
        17: 'Da weinte sie ihm die sieben Tage vor, die das Gelage dauerte. Am siebten Tage aber verriet er es ihr, weil sie ihn gequält hatte. Und sie verriet das Rätsel ihren Landsleuten.',
        18: 'Am siebten Tage sagten die Leute der Stadt zu ihm, bevor er ins Brautgemach ging: "Was ist süßer als Honig, und was ist herber als ein Löwe?" Er sprach zu ihnen: "Hättet ihr nicht mit meinem Kalbe gepflügt, so hättet ihr mein Rätsel nicht gelöst."',
        19: 'Dann überkam ihn der Geist des Herrn. Er stieg nach Askalon hinab und erschlug von ihnen dreißig Mann. Diesen nahm er die Gewandung und gab die Festgewänder den Rätsellösern. Doch ward er darüber zornig und ging zu seines Vaters Haus hinauf.',
        20: 'Simsons Weib aber ward seinem Gesellen zuteil, der sein Nebenbuhler gewesen war.',
    },
    15: {
        1: 'Nach einiger Zeit, in den Tagen der Weizenernte, besuchte Simson sein Weib mit einem Ziegenböckchen. Er sprach: "Ich will zu meinem Weibe in die Kammer gehen." Aber ihr Vater ließ ihn nicht eintreten.',
        2: 'Ihr Vater sagte nämlich: "Ich habe gedacht, du seiest ihr abgeneigt, und so gab ich sie deinem Nebenbuhler. Aber ist nicht ihre jüngere Schwester für dich passender als jene? Sie sei dein an ihrer Statt!"',
        3: 'Da sprach Simson zu ihnen: "Diesmal bin ich schuldfrei an den Philistern, wenn ich ihnen Schlimmes antue."',
        4: 'Und Simson ging, fing dreihundert Füchse, nahm Fackeln, band Schweif an Schweif und tat je eine Fackel zwischen zwei Schweife in die Mitte.',
        5: 'Dann steckte er die Fackeln in Brand und ließ sie los in die Saaten der Philister. So verbrannte er Garben, Halme,Weinberge und Olivenbäume.',
        6: 'Die Philister fragten: "Wer hat dies getan?" Man sagte: "Des Timniters Eidam Simson. Er hat ihm ja sein Weib genommen; dann gab er es seinem Nebenbuhler. Da zogen die Philister hinauf und verbrannten sie und ihren Vater.',
        7: 'Da sprach Simson zu ihnen: "Wenn ihr so tut, dann räche ich mich ein für allemal an euch."',
        8: 'Und er schlug sie ganz gewaltig auf Hügeln und in Tälern. Dann stieg er hinab und weilte in der Felsenkluft von Etam.',
        9: 'Da zogen die Philister herauf, lagerten wider Juda und ließen sich in dem Engpasse nieder.',
        10: 'Da fragte Judas Mannschaft: "Warum zieht ihr gegen uns herauf?" Da sagten sie: "Wir ziehen herauf, Simson zu fesseln und ihm zu tun, wie er uns getan."',
        11: 'Da zogen dreitausend Mann aus Juda nach der Felsenkluft von Etam hinab und sprachen zu Simson: "Weißt du nicht, daß die Philister über uns herrschen? Warum tust du uns dies an?" Er sprach zu ihnen: "Wie sie mir getan, so habe ich ihnen getan."',
        12: 'Und sie sprachen zu ihm: "Wir sind herabgekommen, dich zu fesseln und dich den Philistern auszuliefern." Simson sprach zu ihnen: "Schwört mir, daß ihr mich nicht erschlagt!"',
        13: 'Sie sprachen zu ihm: "Nein! Wir wollen dich nur fesseln und dich in ihre Hand geben. Aber töten wollen wir dich nicht." So fesselten sie ihn mit zwei neuen Stricken und führten ihn aus der Felsenschlucht herauf.',
        14: 'So kam er in den Engpaß, und die Philister jauchzten ihm entgegen. Da kam der Geist des Herrn über ihn. Und die Stricke an seinen Armen wurden wie Fäden, vom Feuer versengt, und die Fesseln glitten ihm von den Händen.',
        15: 'Er fand auch in dem Eselspaß einen Pfahl, streckte seine Hand aus, griff ihn und schlug damit 1.000 Mann.',
        16: 'Und Simson sprach: "Im Eselspaß habe ich sie gründlich geschunden. Im Eselspaß habe ich 1.000 Mann erschlagen."',
        17: 'Als er ausgeredet, warf er ihn in den Paß. Man nannte jenen Ort Ramat Lechi.',
        18: 'Da ward er sehr durstig. Und er rief zum Herrn und sprach: "Du hast durch Deines Dieners Hand diesen großen Sieg geschaffen. Nun werde ich vor Durst sterben und falle dann in der Unbeschnittenen Hand."',
        19: 'Da ließ Gott die Höhle in der Eselsschlucht überquellen, und Wasser floß heraus. Er trank, und sein Geist lebte auf. Daher nannte man sie "Des Rufers Quelle in der Schlucht" bis auf diesen Tag.',
        20: 'Und er richtete Israel zur Zeit der Philister zwanzig Jahre.',
    },
    16: {
        1: 'Simson ging nun nach Gaza. Da sah er dort eine Dirne und ging zu ihr.',
        2: 'Bei den Leuten von Gaza hieß es nun: "Simson ist hierhergekommen." Da stellten sie sich ringsum auf und lauerten ihm ganz heimlich am Stadttor auf. Sie blieben aber die ganze Nacht ruhig, weil sie sagten: "Erst wenn der Morgen tagt, erschlagen wir ihn."',
        3: 'Simson aber schlief bis Mitternacht. Um Mitternacht aber stand er auf, packte die Stadttorflügel samt den beiden Pfosten, hob sie samt dem Riegel aus, legte sie auf seine Schultern und trug sie auf den Gipfel des Berges gegenüber Hebron.',
        4: 'Später liebte er ein Weib am Bache Sorek. Sie hieß Delila.',
        5: 'Da kamen die Philisterfürsten zu ihr herauf und redeten ihr zu: "Berede ihn und sieh zu, wodurch seine Kraft so groß ist und womit wir ihm beikommen können, daß wir ihn fesseln und bezwingen! Dann geben wir, Mann für Mann, dir elfhundert Silberringe."',
        6: 'Da sprach Delila zu Simson: "Sag mir doch, wodurch deine Kraft so groß ist und womit du gefesselt werden mußt, daß man dich bezwinge!"',
        7: 'Simson sprach zu ihr: "Bände man mich mit sieben frischen, feuchten Saiten, dann würde ich schwach und würde wie ein anderer Mensch."',
        8: 'Da brachten die Philisterfürsten sieben frische, feuchte Saiten, und sie band ihn damit.',
        9: 'Bei ihr im Gemache aber saß der Aufpasser. Da sprach sie zu ihm: "Simson! Die Philister sind über dir." Da zerriß er die Saiten, wie ein Wergfaden zerreißt, wenn er Feuer spürt. So blieb seine Kraft unerkundet.',
        10: 'Da sprach Delila zu Simson: "Du hast mich genarrt und mir Lügen vorgeredet. Sag mir jetzt, womit du gefesselt werden mußt!"',
        11: 'Er sagte ihr: "Bände man mich mit neun neuen Stricken, mit denen noch keine Arbeit getan worden, dann würde ich schwach und wie ein anderer Mensch."',
        12: 'Da nahm Delila neue Stricke und fesselte ihn damit. Dann sprach sie zu ihm: "Die Philister sind über dir, Simson." Der Aufpasser aber saß im inneren Gemach. Da riß er sie von seinen Armen wie einen Faden.',
        13: 'Da sprach Delila zu Simson: "Bisher hast du mich genarrt und mir Lügen vorgeredet. Sag mir doch, womit du gefesselt werden mußt!" Da sagte er ihr: "Wenn du die sieben Locken meines Hauptes mit der Decke verflöchtest."',
        14: 'Da klopfte sie an den Pflock und sprach zu ihm: "Simson! Die Philister sind über dir." Da erwachte er aus seinem Schlaf und riß den Pflock, das Geflecht und die Decke aus.',
        15: 'Da sagte sie zu ihm: "Wie kannst du behaupten, du liebest mich? Dein Herz ist nicht bei mir. Dreimal hast du mich genarrt und mir nicht gesagt, wodurch deine Kraft so groß ist."',
        16: 'So setzte sie ihm mit ihren Reden unaufhörlich zu und quälte ihn. Da ward seine Seele zum Sterben ungeduldig.',
        17: 'Und so entdeckte er ihr sein ganzes Herz und sprach zu ihr: "Auf mein Haupt ist noch nie ein Schermesser gekommen. Denn ich bin vom Mutterleibe an ein Gottgeweihter. Würde ich geschoren, so wiche meine Kraft von mir. Ich würde schwach und wäre wie jeder andere Mensch."',
        18: 'Da sah Delila, daß er ihr sein ganzes Herz verraten hatte. Sie sandte hin und ließ die Philisterfürsten rufen und ihnen sagen: "Kommt diesmal! Er hat mir sein ganzes Herz verraten." Da kamen die Philisterfürsten zu ihr und brachten das Geld mit.',
        19: 'Nun ließ sie ihn auf ihrem Schoße einschlafen. Dann rief sie nach einem Schermesser und schnitt ihm die sieben Locken seines Hauptes ab. Da ward es mit ihm immer schwächer, und seine Kraft wich von ihm.',
        20: 'Sie sprach: "Simson! Die Philister sind über dir." Da wachte er aus seinem Schlafe und dachte: "Ich will hinaus wie sonst und mich aufraffen." Er wußte aber nicht, daß der Herr von ihm gewichen war.',
        21: 'Da griffen ihn die Philister und stachen ihm die Augen aus. Dann führten sie ihn nach Gaza hinab und schlugen ihn in eherne Fesseln. Da mußte er die Mühle im Gefängnis drehen.',
        22: 'Sein Haupthaar aber begann wieder zu wachsen, so wie es abgeschoren war.',
        23: 'Nun kamen die Philisterfürsten zusammen, ihrem Gott Dagon ein großes Opferfest zu bereiten und sich zu freuen; denn sie sagten: "Unser Gott hat unseren Feind Simson in unsere Hand gegeben."',
        24: 'Auch das Volk hörte von ihm, und sie priesen ihren Gott; denn sie sagten: "Unser Gott hat unseren Feind in unsere Hand gegeben, den Verwüster unseres Landes, ihn, der so viele von uns erschlagen hat."',
        25: 'Als sie nun guter Dinge wurden, sprachen sie: "Ruft Simson herbei, daß er uns belustige!" Da rief man Simson aus dem Gefängnis, und er mußte sie belustigen. Sie stellten ihn zwischen die Säulen.',
        26: 'Da sprach er zu dem Knaben, der ihn an der Hand hielt: "Laß mich die Säulen betasten, auf denen das Haus ruht! Ich möchte daran lehnen."',
        27: 'Das Haus aber war voller Männer und Weiber. Auch alle Philisterfürsten waren hier zugegen, und auf dem Dache waren an 3.000 Männer und Weiber, die Simsons Spiele zusahen.',
        28: 'Da rief Simson zum Herrn und sprach: "Herr, ach Herr! Gedenke meiner und stärke mich nur diesmal, o Gott! Ich will für meine beiden Augen einmalige Rache an den Philistern nehmen."',
        29: 'Dann umschlang Simson die beiden Mittelsäulen, auf denen das Haus ruhte, und drückte darauf, auf die eine mit dem rechten, auf die andere mit dem linken Arm.',
        30: 'Dann sprach Simson: "Nun sterbe ich mit den Philistern." Und er neigte sich mit Macht, und das Haus fiel auf die Fürsten und alles Volk darin. So wurden es der Toten, die er getötet hatte, bei seinem Tode mehr als derer, die er bei Lebzeiten getötet.',
        31: 'Dann kamen seine Brüder und sein ganzes Vaterhaus herab, holten ihn hinauf und begruben ihn zwischen Sora und Estaol in seines Vaters Manoach Grab. Er hatte Israel zwanzig Jahre gerichtet.',
    },
    17: {
        1: 'Auf dem Gebirge Ephraim war ein Mann namens Micha.',
        2: 'Dieser sprach zu seiner Mutter: "Die elfhundert Silberringe, die dir entwendet worden sind und derentwegen du geflucht und es laut vor mir gesagt hast, dies Geld ist bei mir. Ich habe es entwendet." Da sprach seine Mutter "Mein Sohn! Sei vom Herrn gesegnet!"',
        3: 'Da gab er die elfhundert Silberringe seiner Mutter zurück. Seine Mutter aber sprach: "Ich weihe dieses Geld dem Herrn aus meiner Hand für meinen Sohn, um daraus ein Bildnis mit Umhang zu machen. Als solches gebe ich es dir wieder."',
        4: 'Da brachte er das Geld seiner Mutter. Seine Mutter aber nahm zweihundert Silberringe und gab sie einem Goldschmied. Dieser machte daraus ein Bildnis mit Umhang. Dies kam in Michas Haus.',
        5: 'Und dieser Mann, Micha, machte sich ein Gotteshaus, fertigte Ephod und Teraphim und weihte einen seiner Söhne, und der ward ihm Priester.',
        6: 'Zu jener Zeit war kein König in Israel. Jeder tat, was ihm gut dünkte.',
        7: 'Nun war ein junger Mann aus Bethlehem in Juda aus Judas Sippe. Er war Levite und dort zu Gast.',
        8: 'Nun ging der Mann aus der Stadt Bethlehem in Juda, irgendwo zu Gaste zu sein. So kam er auf das Gebirge Ephraim zu Michas Haus und sprach hier vor.',
        9: 'Micha fragte ihn: "Woher kommst du?" Er antwortete ihm: "Ich bin ein Levite aus Bethlehem in Juda. Ich bin auf der Reise, mich irgendwo niederzulassen."',
        10: 'Da sprach Micha zu ihm: "Bleib bei mir und sei mir Vater und Priester! Ich gebe dir jährlich zehn Silberringe und Kleidung und deinen Lebensunterhalt." Und der Levite ging darauf ein.',
        11: 'So entschloß sich also der Levite, bei dem Manne zu bleiben. Und der junge Mann war bei ihm wie einer seiner Söhne.',
        12: 'Und Micha weihte den Leviten. Und der junge Mann ward sein Priester und blieb in Michas Haus.',
        13: 'Da sprach Micha: jetzt weiß ich, daß der Herr mir wohltun wird, weil ich den Leviten zum Priester habe."',
    },
    18: {
        1: 'Zu jener Zeit gab es keinen König in Israel. Damals suchte sich der Danitenstamm einen Erbbesitz zur Siedlung. Denn ihm war bis dahin inmitten der Stämme Israels kein Erbbesitz zugefallen.',
        2: 'So schickten die Daniten fünf Männer aus ihrer Sippe, aus ihren Beamten, die tüchtigsten Männer aus Sora und Estaol aus, das Land zu erkunden und auszuforschen. Sie sprachen zu ihnen: "Zieht hin! Erforscht das Land!" So kamen sie auf das Gebirge Ephraim zu Michas Haus und übernachteten hier.',
        3: 'Sie waren eben bei Michas Haus. Da hatten sie die Mundart des jungen Leviten erkannt. Und sie kehrten hier ein und fragten ihn: "Wer hat dich hierher gebracht? Was tust du da? Was hast du hier?"',
        4: 'Er sprach zu ihnen: "So und so hat es Micha mit mir gemacht. Er dingte mich, und ich ward sein Priester."',
        5: 'Da sprachen sie zu ihm: "Befrag doch Gott, damit wir wissen, ob unser Weg gelingt, auf dem wir sind!"',
        6: 'Da sprach der Priester zu ihnen: "Geht getrost! Dem Herrn ist euer Weg genehm, auf dem ihr seid."',
        7: 'So zogen die fünf Männer fort und kamen nach Lais. Sie fanden das Volk darin ruhig wohnen, nach Art der Sidonier, sorglos und ruhig. Keiner, der im Lande Macht besaß, tat etwas Schimpfliches. Auch waren sie fern von den Sidoniern und hatten mit niemandem eine Verabredung.',
        8: 'So kamen sie wieder zu ihren Brüdern nach Sora und Estaol, und ihre Brüder fragten sie: "Was sagt ihr?"',
        9: 'Sie sprachen: "Auf! Laßt uns gegen jene ziehen! Wir haben das Land beschaut, und es ist ganz passend. Seid ihr noch unschlüssig? Zögert nicht, hinzuziehen und das Land zu besetzen!',
        10: 'Kommt ihr hin, so kommt ihr zu einem sorglosen Volk, und das Land ist weitläufig, und der Herr gibt es in eure Hand: ein Ort, wo an nichts, was es auf Erden gibt, Mangel ist."',
        11: 'So zogen von dort aus der Danitensippe sechshundert waffengerüstete Männer aus Sora und Estaol.',
        12: 'Sie stiegen hinan und lagerten sich zu Kirjat Jearim in Juda. Daher nennt man jenen Ort "Dans Lager" bis auf diesen Tag. Er liegt hinter Kirjat Jearim.',
        13: 'Von dort zogen sie nach dem Gebirge Ephraim. So kamen sie zu Michas Haus.',
        14: 'Da hoben die fünf Männer an, die ausgezogen waren, das Land von Lais zu erkunden, und sprachen zu ihren Brüdern: "Wißt ihr, daß in diesen Häusern Ephod und Teraphim sind und ein Bildnis mit Umhang? Seht jetzt zu, was ihr tut!"',
        15: 'Sie bogen dorthin ab und kamen in das Haus des jungen Leviten, zu Michas Haus, und fragten ihn nach dem Befinden.',
        16: 'Die sechshundert Mann von den Daniten aber standen kriegsgerüstet am offenen Tor.',
        17: 'Die fünf Männer nun, die das Land zu erkunden ausgezogen und hierher gekommen waren, gingen hinauf und holten das Bildnis, den Ephod, die Teraphim und den Umhang. Der Priester aber stand am offenen Tor, ebenso die sechshundert bewaffneten Männer.',
        18: 'Jene gingen also in Michas Haus und holten das Bildnis, den Ephod, die Teraphim und den Umhang. Da sprach der Priester zu ihnen: "Was macht ihr?"',
        19: 'Sie sprachen zu ihm: "Schweig still! Leg die Hand auf den Mund! Geh mit uns und werde uns Vater und Priester! Willst du lieber Priester für das Haus eines Mannes sein oder Priester für einen Stamm und eine Sippe in Israel?"',
        20: 'Dies gefiel dem Priester. Er nahm den Ephod, die Teraphim und das Bildnis und trat in die Mitte der Leute.',
        21: 'Sie wandten sich nun und zogen ab. Die Kinder aber, das Vieh und die Sklaven stellten sie voran.',
        22: 'Kaum hatten sie sich von Michas Haus entfernt, als die Männer in den Häusern um Michas Haus aufgeboten wurden. Und sie holten die Daniten ein.',
        23: 'Dann riefen sie die Söhne Dans an. Diese wandten sich und sprachen zu Micha: "Was ist dir, daß du das Aufgebot gemacht hast?"',
        24: 'Er sprach: "Ihr nehmt meinen Gott weg, den ich gemacht, samt dem Priester und geht davon. Was bleibt mir noch? Wie könnt ihr fragen: \'Was ist dir?\'"',
        25: 'Da sprachen Dans Söhne zu ihm: "Laß uns nichts weiter hören! Sonst könnten Männer erbitterten Gemüts euch anfallen. Und dann kannst du dich und dein Haus zusammensuchen."',
        26: 'So zogen die Daniten ihres Wegs. Micha aber sah, daß sie ihm zu stark waren und kehrte heim.',
        27: 'Sie nahmen also mit, was Micha hatte machen lassen, samt dem Priester, den er besaß. So zogen sie bis Lais, gegen ein ruhig und sorglos lebendes Volk, schlugen sie mit des Schwertes Schärfe und verbrannten die Stadt.',
        28: 'Niemand aber half; denn sie lag zu weit von Sidon und hatte mit niemandem Verabredung. Sie lag in der Ebene von Bet Rechob. Sie bauten die Stadt wieder auf und siedelten darin.',
        29: 'Und sie nannten die Stadt "Dan" nach dem Namen ihres Ahnen Dan, der Israel geboren ward. Früher hieß die Stadt Lais.',
        30: 'Die Daniten stellten nun das Bildnis auf, und Jonatan, der Sohn Gersoms und Enkel Manasses, er und seine Söhne wurden Priester für den Stamm der Daniten bis zur Wegführung aus dem Lande.',
        31: 'Sie hatten das Bildnis, das Micha gemacht hatte, die ganze Zeit aufgestellt, solange das Gotteshaus in Silo war.',
    },
    19: {
        1: 'In jener Zeit, als es keinen König in Israel gab, war ein levitischer Mann auf der Rückseite des Gebirges Ephraim zu Gast. Er nahm sich ein Mädchen aus Bethlehem in Juda zum Nebenweib.',
        2: 'Sein Nebenweib aber betrog ihn und ging von ihm in ihres Vaters Haus nach Bethlehem in Juda. Dort lebte sie vier Monate.',
        3: 'Da machte sich ihr Mann auf und ging ihr nach, ihr zuzureden und sie zurückzugewinnen. Er aber hatte seinen Burschen und ein paar Esel bei sich. Sie führte ihn nun in ihres Vaters Haus. Da sah ihn des Mädchens Vater und freute sich über seine Ankunft.',
        4: 'Und sein Schwiegervater, des Mädchens Vater, gab ihm die Hand, und er blieb drei Tage bei ihm. Sie aßen und tranken und blieben über Nacht.',
        5: 'Am vierten Tage standen sie früh auf, und er erhob sich zu gehen. Da sprach des Mädchens Vater zu seinem Schwiegersohn: "Stärke dein Herz mit einem Bissen Brot! Hernach mögt ihr reisen."',
        6: 'Sie setzten sich, aßen beide zusammen und tranken. Dann sprach des Mädchens Vater zu dem Mann: "Entschließe dich und bleibe über Nacht und sei guter Dinge!"',
        7: 'Der Mann aber stand auf, um zu gehen. Aber sein Schwiegervater drang in ihn, und er blieb nochmals über Nacht da.',
        8: 'Am fünften Tage stand er früh auf, um zu gehen. Da sprach des Mädchens Vater: "Stärke doch dein Herz und verweilet bis zur Neige des Tages!" So aßen sie miteinander.',
        9: 'Dann stand der Mann auf, um zu gehen, er, sein Nebenweib und sein Diener. Da sprach sein Schwiegervater, des Mädchens Vater, zu ihm: "Der Tag neigt sich zum Abendwerden. Bleibt doch über Nacht! Der Tag geht zur Neige, bleibe hier über Nacht und sei guter Dinge! Morgen früh zieht eures Wegs, daß du zu deinem Zelte kommst!"',
        10: 'Aber der Mann wollte nicht mehr übernachten. Er stand auf, zog fort und kam bis vor Jebus, das ist Jerusalem. Er hatte ein Paar gesattelter Esel bei sich und sein Nebenweib.',
        11: 'Sie waren eben bei Jebus, als es spät am Tage wurde! Da sprach der Bursche zu seinem Herrn: "Komm! Laßt uns in dieser Jebusiterstadt einkehren und hier übernachten!"',
        12: 'Aber sein Herr sprach zu ihm: "Wir wollen nicht in einer fremden Stadt einkehren, in der kein Israelite ist. Wir ziehen weiter bis Gibea."',
        13: 'Dann sprach er zu seinem Burschen: "Komm! Wir wollen nach einer der Ortschaften gehen! Wir übernachten in Gibea oder in Rama."',
        14: 'So zogen sie des Weges weiter. Da ging die Sonne unter bei Gibea in Benjamin.',
        15: 'Hier bogen sie nun vom Wege ab, um in Gibea zu übernachten. Als er ankam, setzte er sich auf den Marktplatz der Stadt. Aber niemand nahm sie ins Haus zum Übernachten.',
        16: 'Da kam ein alter Mann abends von seiner Feldarbeit. Der Mann war vom Gebirge Ephraim und selber Fremdling zu Gibea. Die Leute des Ortes aber waren Benjaminiten.',
        17: 'Er hob nun seine Augen und sah den Wandersmann auf dem Marktplatz der Stadt. Da fragte der alte Mann: "Wohin gehst du? Woher kommst du?"',
        18: 'Er sprach zu ihm: "Wir ziehen von Bethlehem in Juda nach der Rückseite des Gebirges Ephraim. Ich bin von dort. Ich reiste nach Bethlehem in Juda. Ich bin nun unterwegs nach dem eigenen Hause. Aber niemand nimmt mich in sein Haus.',
        19: 'Wir haben Stroh und Futter für unsere Esel. Auch Brot und Wein für mich und deine Magd und für den Burschen sind bei deinem Sklaven. Es fehlt an nichts."',
        20: 'Da sprach der alte Mann: "Friede sei mit dir! Mir obliege all dein Mangel allein! Nur auf der Straße darfst du nicht übemachten."',
        21: 'Dann führte er ihn in sein Haus und fütterte die Esel. Sie aber wuschen sich die Füße, aßen und tranken.',
        22: 'Sie taten eben ihrem Herzen gütlich. Da umringten die Männer der Stadt, Teufelsbuben, das Haus, klopften an die Tür und sprachen zu dem alten Mann, dem Herrn des Hauses: "Gib den Mann heraus, der in dein Haus gekommen, daß wir ihn erkennen!"',
        23: 'Da ging der Mann, der Hausherr, zu ihnen hinaus und sprach zu ihnen: "Nicht doch! Meine Brüder! Tut doch nichts Böses! Nachdem dieser Mann in mein Haus gekommen, dürft ihr keine solche Schandtat tun.',
        24: 'Da ist meine jungfräuliche Tochter und ihre Dienerin. Ich will sie herausgeben. Ihnen tut Gewalt an! Mit ihnen tut nach eurer Laune! Aber diesem Manne dürft ihr keine solche Schandtat antun."',
        25: 'Aber die Männer wollten nicht auf ihn hören. Da ergriff der Mann sein Nebenweib und brachte sie ihnen auf die Straße. Und sie erkannten sie und trieben Mutwillen mit ihr die ganze Nacht bis zum Morgen. Sie ließen sie erst los beim Anbruch der Morgenröte.',
        26: 'Bei der Morgenwende aber kam das Weib und fiel nieder vor der Haustür des Mannes, bei dem ihr Herr war, und lag so bis zum lichten Tage.',
        27: 'Ihr Herr aber stand am Morgen auf, öffnete die Haustür und trat hinaus, um seines Weges zu ziehen. Da lag das Weib, sein Nebenweib, vor der Haustür, die Hände auf der Schwelle.',
        28: 'Er sprach sie an: "Steh auf! Wir wollen fort." Aber keine Antwort! Da lud er sie auf den Esel. Und der Mann machte sich auf und zog nach seiner Heimat.',
        29: 'Als er heimkam, nahm er das Messer, faßte sein Nebenweib, zerstückelte es völlig in zwölf Stücke und sandte sie umher im ganzen Bereiche Israels.',
        30: 'Da rief jeder, der es sah: "Solches ist nicht geschehen und nicht gesehen worden seit der Zeit, da Israels Söhne aus Ägypterland gezogen, bis auf diesen Tag. Denkt darüber nach! Ratet und sprechetl"',
    },
    20: {
        1: 'Da zogen alle Söhne Israels aus, und die Gemeinde sammelte sich wie ein Mann von Dan bis Beerseba, dazu das Land Gilead, vor dem Herrn auf der Mispa.',
        2: 'Und die Vorkämpfer des ganzen Volkes, alle Stämme Israels, stellten sich ein in der Gemeinde des Gottesvolkes, 400.000 Mann zu Fuß, Schwertträger.',
        3: 'Die Benjaminiten aber hörten, die Söhne Israels seien nach der Mispa gezogen. Die Söhne Israels hatten nämlich sagen lassen: "Sagt an! Wie ist diese schlimme Tat geschehen?"',
        4: 'Da antwortete der levitische Mann, der Mann des gemordeten Weibes, und sprach: "Ich bin mit meinem Nebenweibe nach Gibea in Benjamin gekommen zu übernachten.',
        5: 'Da erhoben sich Gibeas Bürger gegen mich und umringten meinetwegen nachts das Haus. Mich umzubringen, sind sie bedacht gewesen, und mein Nebenweib haben sie so vergewaltigt, daß es starb.',
        6: 'Da nahm ich mein Nebenweib, zerstückelte es und sandte es im ganzen Bereiche des israelitischen Eigenbesitzes umher. Denn sie haben in Israel Niedertracht und Schandtat begangen.',
        7: 'Wohlan! Ihr Söhne Israels insgesamt! Schafft hier Bescheid und Rat!"',
        8: 'Da erhob sich das ganze Volk wie ein Mann und sprach: "Keiner gehe in sein Zelt! Keiner nach Hause!',
        9: "Nun denn! Das ist es, was wir mit Gibea tun wollen: 'Nach dem Lose über sie her!'",
        10: 'Wir nehmen zehn Mann von hundert aus allen Stämmen Israels, hundert von tausend und tausend von zehntausend. Sie sollen Zehrung für das Kriegsvolk schaffen, auf daß das Volk gegen Gibea in Benjamin ziehe, nach der Schandtat, die es in Israel verübte!"',
        11: 'Da brachte alle Mannschaft Israels wie ein Mann Zehrung in die Stadt.',
        12: 'Dann sandten die Stämme Israels Männer zum ganzen Benjaminstamm mit der Botschaft: "Welch eine Untat ist bei euch geschehen?',
        13: 'Gebt die Männer heraus, die Teufelsbuben, in Gibea, daß wir sie töten und das Schlimme aus Israel tilgen!" Aber die Benjaminiten wollten nicht auf die Stimme ihrer israelitischen Brüder hören.',
        14: 'Und die Benjaminiten aus den anderen Städten versammelten sich in Gibea, gegen die Israeliten in den Kampf zu ziehen.',
        15: 'Und die Benjaminiten aus den Städten wurden an jenem Tag gemustert, 26.000 Schwertbewaffnete, außer Gibeas Einwohnern. Dann wurden 700 Auserlesene gemustert.',
        16: 'Von all diesem Volk waren 700 Auserlesene linkshändig. Jeder von ihnen schleuderte mit Steinen haarscharf, ohne zu fehlen.',
        17: 'Auch Israels Mannschaft ward gemustert. Ohne Benjamin waren es 400.000 Schwertbewaffnete, lauter Kriegsleute.',
        18: 'Sie erhoben sich nun und zogen nach Betel hinauf und befragten Gott. Die Israeliten fragten: "Wer von uns zieht zuerst zum Kampfe wider die Benjaminiten hinauf?" Der Herr sprach: "Juda zuerst!"',
        19: 'Am Morgen erhoben sich die Israeliten und lagerten gegen Gibea.',
        20: 'Da zog Israels Mannschaft zum Kampfe gegen Benjamin bei Gibea. Israels Mannschaft aber bot ihnen den Kampf an.',
        21: 'Da rückten die Benjaminiten aus Gibea und streckten an jenem Tage von Israel 22.000 Mann nieder.',
        22: 'Da ermannte sich das Kriegsvolk, Israels Mannschaft, und bot ihnen nochmals den Kampf an, am selben Platze, wo sie ihn am ersten Tage angeboten hatten.',
        23: 'Dann gingen die Israeliten hinauf und weinten vor dem Herrn bis zum Abend. Dann befragten sie den Herrn und sprachen: "Soll ich noch einmal zum Kampf gegen meinen Bruder Benjamin ausrücken?" Der Herr sprach: "Zieht gegen sie!"',
        24: 'Am zweiten Tage nun zogen die Israeliten gegen die Benjaminiten.',
        25: 'Und am zweiten Tage zog ihnen Benjamin aus Gibea entgegen und streckte von den Israeliten abermals 18.000 Mann nieder, lauter Schwertbewaffnete.',
        26: 'Da gingen alle Israeliten, und zwar das gesamte Kriegsvolk, hinauf. Sie kamen nach Betel und weinten und saßen dort vor dem Herrn und fasteten an jenem Tage bis Abend. Dann brachten sie Brand- und Mahlopfer vor dem Herrn dar.',
        27: 'Darauf befragten die Israeliten den Herrn. Denn dort war zu jener Zeit die Bundeslade Gottes.',
        28: 'Zu jener Zeit diente ihm Pinechas, Eleazars Sohn und Aarons Enkel. Sie sprachen: "Soll ich noch einmal zum Kampf gegen meinen Bruder Benjamin ziehen oder soll ich es lassen?" Der Herr sprach: "Zieht aus! Denn morgen gebe ich ihn in deine Hand."',
        29: 'Nun legte Israel einen Hinterhalt rings um Gibea.',
        30: 'Dann zogen die Israeliten gegen die Benjaminiten am dritten Tage und stellten sich wider Gibea wie die vorigen Male auf.',
        31: 'Da rückten die Benjaminiten dem Kriegsvolk entgegen. Sie ließen sich aber von der Stadt weglocken und begannen, wie die vorigen Male, einige vom Kriegsvolk zu erschlagen auf den Straßen, deren eine nach Betel und die andere nach Gibea führt, auf freiem Felde, gegen dreißig Mann von Israel.',
        32: 'Da dachten die Benjaminiten: "Sie werden von uns geschlagen wie das erstemal." Die Israeliten aber hatten gesagt: "Laßt uns fliehen, daß wir sie von der Stadt nach den Straßen locken."',
        33: 'Da erhob sich Israels ganze Mannschaft aus ihrem Ort und stellte sich bei Baal Tamar auf. Dann brach Israel aus seinem Standort im Hinterhalt hervor, aus einer Waldlichtung bei Geba.',
        34: 'So kamen, Gibea gegenüber, 10.000 aus ganz Israel erlesene Männer heran. Und der Kampf ward heftig. Sie wußten aber nicht, daß das Verderben ihnen nahte.',
        35: 'So schlug der Herr durch Israel Benjamin. Und die Israeliten schlugen an jenem Tag von Benjamin 25.100 Mann, lauter Schwertbewaffnete.',
        36: 'Die Benjaminiten sahen nun, daß sie geschlagen waren. Israels Mannschaft aber gab Benjamin Raum, weil sie sich auf den Hinterhalt verließen, den sie bei Gibea gelegt hatten.',
        37: 'Nun brach plötzlich der Hinterhalt vor und schwärmte gegen Gibea aus. Und der Hinterhalt rückte vor und schlug die ganze Stadt mit des Schwertes Schärfe.',
        38: 'Die Mannschaft Israels aber hatte mit dem Hinterhalt, der einfallen sollte, eine Abmachung getroffen, er solle eine starke Rauchsäule aus der Stadt aufsteigen lassen.',
        39: 'Nun wandte Israels Mannschaft sich im Kampf, und Benjamin begann, schon etliche der Mannschaft Israels, etwa dreißig Mann, zu erschlagen; denn sie dachten: Sie erliegen uns wie in der ersten Schlacht.',
        40: 'Da begann der Brand, und aus der Stadt stieg eine Rauchsäule auf. Als Benjamin zurückschaute, war die ganze Stadt himmelhoch in Flammen aufgegangen.',
        41: 'Israels Mannschaft aber hatte kehrt gemacht; so ward Benjamins Mannschaft verwirrt. Denn sie sahen, daß sie das Verderben ereilt hatte.',
        42: 'So wandten sie sich vor Israels Mannschaft auf den Weg zur Wüste. Der Kampf hatte sich an sie geheftet, und die aus der Vorhut setzten ihnen zu.',
        43: 'Inzwischen hatten sie Benjamin umzingelt, verfolgt und mühelos niedergekämpft bis östlich Gibea gegenüber.',
        44: 'Dabei fielen von Benjamin 18.000 Mann, lauter tapfere Männer.',
        45: 'Sie wandten sich zur Flucht nach der Wüste gegen den Rimmonfelsen hin. Jene aber hielten auf den Straßen unter ihnen eine Nachlese von fünftausend Mann und verfolgten sie bis zur Vernichtung und schlugen von ihnen noch zweitausend Mann.',
        46: 'So waren aus Benjamin an jenem Tag insgesamt 25.000 Schwertbewaffnete gefallen, lauter tapfere Männer.',
        47: 'Sie wandten sich nun und flohen nach der Wüste gegen den Rimmonfelsen hin, sechshundert Mann. Und sie blieben beim Rimmonfelsen vier Monate.',
        48: 'Israels Mannschaft aber kehrte zu den anderen Benjaminiten zurück und schlug sie mit des Schwertes Schärfe, außerhalb der Städte, von den Männern bis zum Vieh, alles, was sich vorfand. Auch alle vorgefundenen Städte steckten sie in Brand.',
    },
    21: {
        1: 'Israels Mannschaft aber hatte auf der Mispa geschworen: "Keiner von uns darf seine Tochter Benjamin zum Weibe geben."',
        2: 'Und das Volk kam nach Betel und saß dort bis zum Abend vor Gott. Und sie erhoben ihre Stimme, weinten laut und sprachen:',
        3: '"Warum, Herr, Gott Israels, ist dies in Israel geschehen, daß heute aus Israel ein Stamm vermißt wird?"',
        4: 'Das Volk aber baute am anderen Morgen früh dort einen Altar und brachte Brand- und Dankopfer dar.',
        5: 'Dann fragten die Israeliten: "Wer von allen Stämmen Israels ist es, der nicht mit der Gemeinde zum Herrn heraufgezogen ist?" Denn der große Schwur war gegen den ausgesprochen worden, der nicht zum Herrn nach der Mispa käme: "Er soll des Todes sterben!"',
        6: 'Da tat es den Israeliten leid um ihren Bruder Benjamin, und sie sprachen: "Heute ist ein Stamm aus Israel ausgerissen.',
        7: 'Wie können wir den Übriggebliebenen zu Weibern verhelfen? Wir haben ja beim Herrn geschworen, daß wir keine unserer Töchter an sie verheiraten wollen?"',
        8: 'Da sprachen sie: "Welcher von Israels Stämmen ist nicht zum Herrn nach der Mispa gezogen?" Da fand sich, daß aus Jabes in Gilead niemand ins Lager zur Versammlung gekommen war.',
        9: 'Da ward das Volk gemustert, und wirklich war aus Jabes in Gilead niemand da.',
        10: 'Da sandte die Gemeinde 12.000 der tapfersten Männer dahin und befahl ihnen: "Geht hin und schlagt die Einwohner von Jabes in Gilead mit des Schwertes Schärfe, Weiber und Kinder!',
        11: 'Und so sollt ihr es machen: Bannt alle Mannsbilder und alle Weiber, die männliches Beilager erkannt!"',
        12: 'Da fanden sich unter den Einwohnern von Jabes in Gilead 400 jungfräuliche Mädchen, die noch keinen Mann in männlichem Beilager erkannt hatten. Diese brachten sie ins Lager zu Silo im Lande Kanaan.',
        13: 'Dann sandte die ganze Gemeinde hin und verhandelte mit den Benjaminiten beim Rimmonsfelsen. Und sie entboten ihnen Frieden.',
        14: 'Da kehrten die Benjaminiten in jener Zeit zurück, und man gab ihnen Weiber, die man von den Weibern zu Jabes in Gilead am Leben gelassen hatte. Aber sie reichten ihnen nicht.',
        15: 'Da tat es dem Volk um Benjamin leid, daß der Herr einen Riß in die Stämme gemacht hatte.',
        16: 'So sprachen die Ältesten der Gemeinde: "Wie können wir den Übriggebliebenen zu Weibern verhelfen? Sind doch aus Benjamin die Weiber ausgerottet!"',
        17: 'Sie sprachen: "Eine Möglichkeit der Rettung gäbe es für Benjamin! Kein Stamm aus Israel darf doch getilgt werden.',
        18: 'Wir aber können ihnen keine Weiber aus unseren Töchtern geben; denn die Israeliten haben geschworen: \'Verflucht sei, wer Benjamin ein Weib gibt!\'"',
        19: 'Dann sprachen sie: "Das Fest des Herrn ist jedes Jahr zu Silo, nördlich von Betel, östlich der Straße von Betel nach Sichem und südlich von Lebona."',
        20: 'Sie rieten nun den Benjaminiten: "Geht und lauert in den Weinbergen!',
        21: 'Seht ihr, daß Silos Töchter herauskommen, Reigen zu tanzen, dann brecht aus den Weinbergen hervor und raubt euch jeder aus Silos Töchtern ein Weib! Dann geht heim ins Land Benjamin!',
        22: 'Kommen dann ihre Väter oder Brüder, bei uns zu klagen, dann sagen wir ihnen: \'Seht es ihnen nach! Haben wir nicht im Krieg jeden seines Weibes beraubt? Hättet ihr sie ihnen gegeben, dann wäret ihr jetzt schuldig.\'"',
        23: 'Die Benjaminiten taten so und holten sich aus den Tänzerinnen die nötige Zahl Weiber, die sie raubten. Dann kehrten sie in ihren Erbbesitz heim, bauten die Städte wieder auf und siedelten darin.',
        24: 'Von dort gingen die Israeliten zu jener Zeit auseinander, jeder zu seinem Stamm und seiner Sippe. So zogen sie von dort ab, jeder in seinen Erbbesitz.',
        25: 'Zu jener Zeit gab es in Israel keinen König, und jeder tat, was ihm gut dünkte.',
    },
}
